/**
 * btn system reset
**/

input.btn,
button.btn {
	overflow: visible;
	margin: 0;
	padding: 0;
	cursor: pointer;
	border: hidden;
	background-color: transparent;
	appearance: none;
}

.btn svg {
	display: block;
	position: relative;
	top: 0;
	left: 0;
}

$btn-module-a-accent: (
	normal-00: color(base, 100),
	normal-01: color(base, 080),
	normal-02: color(base, 060),
	normal-03: color(base, 040),
	normal-10: color(base, 000),
	
	accent-01: color(primary, 050),
	accent-02: color(secondary, 050),
	accent-03: color(secondary, 060),
	accent-04: color(secondary, 070),
);

$btn-module-a-outline: (
	'small-3x'		20rem 1.40,
	'small-2x'		24rem 1.40,
	'small-1x'		28rem 1.50,
	'medium'		32rem 1.50,
	'large-1x'		36rem 1.50,
	'large-2x'		40rem 1.50,
	'large-3x'		44rem 1.50,
	'large-4x'		48rem 1.50,
	'large-5x'		52rem 1.50,
	'large-6x'		56rem 1.50,
);

/**
 * btn module-a reset
**/
a.btn.module-a {
	&:not(:hover) {
		text-decoration: none;	
	}
}

.btn.module-a {
	// general
	display: inline-flex;
	align-items: center;
	justify-content: center;
	@include font((family: default)...);

	.btn-text {
		display: flex;
		align-items: center;
		justify-content: center;
		text-align: center;
	}

	// accent
	@each $name, $color in $btn-module-a-accent {
		&.#{$name} {
			color: $color;
		}
	}

	// outline
	@each $name, $line-height, $font-size in $btn-module-a-outline {
		&.#{$name} {
			line-height: $line-height;
			font-size: calc($line-height / $font-size);
		}
	}
}



