// btn module-b reset
 a.btn.module-b {
	 text-decoration: none;
 }

 .btn.module-b {
	// general
	display: inline-flex;
	align-items: center;
	justify-content: center;
	box-sizing: border-box;
	border-style: solid;
	@include font((family: default)...);

	&.style-b {
		border-radius: 4rem;
	}

	&.disabled {
		color: color(base, 040);
		border-color: color(base, 020);
		background-color: color(base, 020);
		pointer-events: none;
	}

	.btn-text {
		display: flex;
		align-items: center;
		justify-content: center;
		white-space: nowrap;
		text-align: center;
	}

	// icon
	// 1. 아이콘의 유무는 특정 클래스명으로 한다.
	// 2. 아이콘의 위치는 특정 클래스명으로 한다.
	// 3. 아이콘의 종류는 지정한 아이콘셋(클래스명)으로 한다.
	// 4. 아이콘의 사이즈는 outline별로 달라야 한다.
	//		1) 행간에 맞춘다.
	//		2) 별도의 사이즈를 지정한다.
	// 5. 무조건 중앙에 또는 상단 기준을 택일
	// 6. accent에 따라 컬러를 다르게 한다.

	&[class*=ltr-] .btn-text::before,
	&[class*=rtl-] .btn-text::after {
		content: '';
		display: block;
		background-repeat: no-repeat;
		background-size: cover;
		mask-repeat: no-repeat;
		mask-position: center;
		mask-size: cover;
	}

	&[class*="attr-"] {
		&::before {
			content: '';
			flex-shrink: 0;
			display: block;
			width: 24rem;
			height: 24rem;
			margin: 0 auto;
			background-repeat: no-repeat;
			background-position: center;
			background-size: auto 100%;
			mask-repeat: no-repeat;
			mask-size: auto 100%;
			mask-position: center
		}	
		.btn-text {
			@include hidden();
		}
	}

	&.attr-upload {
		&::before {
			mask-image: icon(upload, color(normal, 010));
		}
	}
	
	&.attr-plus {
		&::before {
			mask-image: icon(plus, color(normal, 010));
		}
	}

	&.attr-minus {
		&::before {
			mask-image: icon(minus, color(normal, 010));
		}
	}

	&.attr-delete {
		&::before {
			mask-image: icon(delete, color(normal, 010));
		}
	}


	// accent
	@each $accent-name in $btn-module-b-accent {
		&.#{nth($accent-name, 1)} {

			// @debug "divider offset: #{nth($accent-name, 1)}";
			@each $type-name, $color, $border-color, $background-color in map-get($btn-module-b-accent, nth($accent-name, 1)) {
				&.type-#{$type-name}:not(.disabled) {
					color: $color;
					border-color: $border-color;
					background-color: $background-color;
					
					&[class*=ltr-] .btn-text::before,
					&[class*=rtl-] .btn-text::after {
						background-color: $color;
					}

					&[class*="attr-"] {
						&::before {
							background-color: $color;
						}
					}
				}
			}
		}
	}

	// outline
	@each $name, $line-height, $font-size, $font-weight, $border-width in $btn-module-b-outline {
		&.#{$name} {
			padding-right: map-get($GLOBAL_OUTLINE, $name) * 0.25;
			padding-left: map-get($GLOBAL_OUTLINE, $name) * 0.25;
			height: map-get($GLOBAL_OUTLINE, $name);

			font-weight: $font-weight;
			line-height: $line-height;
			font-size: calc($line-height / $font-size);
			border-width: $border-width;

			&.style-c {
				border-radius: map-get($GLOBAL_OUTLINE, $name) * 0.5;
			}

			&.file {
				width: map-get($GLOBAL_OUTLINE, $name);
				padding: 0;
			}

			// icon
			&[class*=ltr-] .btn-text::before,
			&[class*=rtl-] .btn-text::after {
				width: $line-height;
				min-width: $line-height;
				height: $line-height;
			}
			
			&[class*=ltr-] {
				padding-left: map-get($GLOBAL_OUTLINE, $name) * 0.2;
				// padding-left: (map-get($GLOBAL_OUTLINE, $name) * 0.333) - ($line-height * 0.25);
				.btn-text {
					&::before {
						// margin-right: $line-height * 0.333;
						margin-right: 4rem;
					}
				}
			}

			&[class*=rtl-] {
				padding-right: map-get($GLOBAL_OUTLINE, $name) * 0.2;
				// padding-right: (map-get($GLOBAL_OUTLINE, $name) * 0.333) - ($line-height * 0.25);
				.btn-text {
					&::after {
						// margin-left: $line-height * 0.333;
						margin-left: 4rem;
					}
				}
			}

			&[class*="attr-"] {
				width: map-get($GLOBAL_OUTLINE, $name);
				padding: 0;
			}
		}
	}
}

