// button-display
.button-display.module-a {
	display: flex;

	.button-area {
		display: flex;
		position: relative;
	}

	// style-a
	&.style-a {
		.button-area {
			.btn.flex {
				flex: 1 1 100%;
				width: 100%;
			}
		}

		&.type-a {
			.button-area {
				flex: 1 1 100%;
				justify-content: flex-start;
			}
		}
	
		&.type-b {
			.button-area {
				flex: 1 1 100%;
				justify-content: flex-end;
			}
		}
	
		&.type-c {
			justify-content: center;

			.button-area {
				justify-content: center;
			}
		}

		&.type-d {
			justify-content: space-between;
		}

