		row-gap: 8rem;

		.button-area {
			flex-shrink: 0;
			flex-direction: column;
			row-gap: 8rem;

			.btn {
				flex-shrink: 0;

				.btn-text {
					display: flex;
					align-items: center;
					justify-content: space-between;
					white-space: nowrap;
					text-align: left;
				}
			}
		}
	}
}

// button-display
.button-display.module-b {
	.button-area {
		display: flex;
		flex-wrap: wrap;
		column-gap: 8rem;
		row-gap: 8rem;

		.btn {
			&:nth-child(2):not(:nth-last-child(2)),
			&:nth-child(1) {
				flex: 1 1 100%;
			}

			&:nth-child(1) ~ .btn {
				@include display-column(2, '8rem');
			}
		}
	}
}