.bui-tab-target {
	&:not(.active) {
		@include hidden;
	}
}


/**
 * @name		tab-display
**/
.tab-display {
	.tab-list {
		display: flex;
		margin: 0;
		padding: 0;
		list-style: none;

		button.tab-item {
			overflow: visible;
			margin: 0;
			padding: 0;
			cursor: pointer;
			border: hidden;
			background-color: transparent;
			appearance: none;
			@include font((family: default)...);
		}

		.tab-item {			
			.tab-text {
				display: flex;
				position: relative;
				justify-content: center;
				align-items: center;
				text-decoration: none;
				text-align: center;
				box-sizing: border-box;
			}

			&.current {
				z-index: 0;
			}
		}
	}

	// tab type
	&.type-a { 
		.tab-list{
			justify-content: flex-start;
		}
	}

	&.type-b { 
		.tab-list{
			justify-content: flex-end;
		}
	}

	&.type-c { 
		.tab-list{
			justify-content: center;
		}
	}

	&.type-d { 
		.tab-list{
			.tab-item {
				flex: 1 1 100%;
				width: 100%;
			}
		}
	}
}

/**
 * @name		tab-display
 * @moudle		module-c
**/
.tab-display.module-c {
	display: flex;

	.tab-list {
		background-color: color(normal, 000);

		.tab-item {
			position: relative;

			&::before {
				content: '';
				display: block;
				position: absolute;
				top: -1rem;
				right: -1rem;
				bottom: -1rem;
				left: -1rem;
			}

			+.tab-item {
				border-left: 1rem solid color(normal, 040);
			}

			.tab-text {
				display: flex;
				align-items: center;
				column-gap: 4rem;
				position: relative;
				padding: 0 40rem;
				// min-width: 128rem;
				height: calc(40rem - 2rem);
				@include font((outline: small-2x, size: 1.5, weight: medium)...);
				color: color(normal, 040);
				box-sizing: border-box;
			}

			&:focus-within,
			&.current {
				z-index: 1;
			}

			&.current {
				&::before {
					background-color: color(accent, 010);
				}

				.tab-text {
					color: color(normal, 000);
				}
			}
		}
	}

	&.style-b {
		.tab-list {
			border: 1rem solid color(normal, 040);
			border-radius: 4rem;

			.tab-item {
				&:first-child::before {
					border-top-left-radius: 4rem;
					border-bottom-left-radius: 4rem;
				}
	
				&:last-child::before {
					border-top-right-radius: 4rem;
					border-bottom-right-radius: 4rem;
				}
			}
		}
	}
}

/**
 * @name		tab-display
 * @moudle		module-d
**/
.tab-display.module-d {
	.tab-list {
		overflow: hidden;
		position: relative;
		background-color: color(base, 005);
		border-radius: 12rem 12rem 0rem 0rem;

		&::before {
			content: '';
			display: block;
			position: absolute;
			bottom: 0;
			z-index: 1;
			width: 100%;
			height: 1rem;
			background-color: color(normal, 050);
		}

		.tab-item {
			display: flex;
			flex-shrink: 0;
			align-items: center;
			position: relative;
			background-color: color(base, 005);
			border-width: 1rem 1rem 0rem 1rem;
			border-style: solid;
			border-color: color(base, 005);
			box-sizing: border-box;

			&:not(:first-child) .tab-text::after{
				content: '';
				display: block;
				position: absolute;
				z-index: 1;
				top: 0;
				left: -1rem;
				width: 1rem;
				height: 100%;
				background-color: color(normal, 050);
			}
			
			&.current .tab-text::after,
			&.current +.tab-item .tab-text::after {
				display: none;
			}
			
			.tab-text {
				display: flex;
				align-items: center;
				position: relative;
				padding: 16rem 18rem;
				@include font((outline: small-2x, size: 1.5, weight: medium)...);
				color: color(normal, 030);

				.number {
					display: flex;
					margin-left: 4rem;
					padding: 2rem 8rem;
					background-color: color(normal, 030);
					border-radius: 90rem;
					@include font((outline: small-4x, size: 1.3, weight: bold)...);
					color: color(normal, 000);
				}
			}

			&.current {
				position: relative;
				z-index: 1;
				background-color: color(primary, 005);
				border-color: color(primary, 010);
				border-radius: 12rem 12rem 0rem 0rem;

				.tab-text {
					color: color(accent, 060);
					
					.number {
						background-color: color(accent, 060);
					}
				}
			}

			&[class*="attr-"] {
				.tab-text  {
					&::before {
						content: '';
						flex-shrink: 0;
						display: block;
						width: 24rem;
						height: 24rem;
						margin: 0 8rem 0 0;
						background-repeat: no-repeat;
						background-size: cover;
						background-position: center;
						background-color: color(normal, 030);
						mask-repeat: no-repeat;
						mask-size: cover;
						mask-position: center;
					}
				}
				&.current {
					.tab-text {
						&::before {
							background-color: color(accent, 060);
						}
					}
				}		
			}

			&.attr-completion {
				.tab-text  {
					&::before {
						mask-image: icon(list, color(normal, 030));
					}
				}		
			}

			&.attr-activation {
				.tab-text  {
					&::before {
						mask-image: icon(on, color(normal, 030));
					}
				}		
			}

			&.attr-registration {
				.tab-text  {
					&::before {
						mask-image: icon(write, color(normal, 030));
					}
				}		
			}
		}
	}

	&.style-b {
		.tab-list {
			display: inline-flex;
			
			.tab-item {
				
				&:first-child{
					border-radius: 12rem 0 0 0;
				}

				&:last-child {
					border-radius: 0 12rem 0 0;				
				}

				&.current {
					&:first-child,
					&:last-child {
						border-radius: 12rem 12rem 0rem 0rem;
					}

					.tab-text {
						border-radius: 12rem 12rem 0 0;
					}

					
				}
				
				.tab-text {
				}
			}
		}
	}
}

/**
 * @name		tab-display
 * @moudle		module-e
**/
.tab-display.module-e {
	.tab-list {
		column-gap: 12rem;

		.tab-item {
			display: flex;
			align-items: center;
			
			.tab-text {
				display: flex;
				align-items: center;
				column-gap: 4rem;
				min-width: 128rem;
				padding: 8rem 20rem;
				background-color: color(normal, 000);
				border: 1rem solid color(normal, 040);
				box-sizing: border-box;
				@include font((outline: small-2x, size: 1.5)...);
				color: color(base, 060);
			}

			&.current {
				.tab-text {
					background-color: color(primary, 005);
					border-color: color(accent, 010);
					color: color(accent, 010);
				}
			}
		}
	}

	&.style-b {
		.tab-list {
			.tab-item {
				&.current {
					.tab-text {}
				}
				.tab-text {
					border-radius: 4rem;
				}
			}
		}
	}
}

/**
 * @name		dropdown
**/
@mixin dropdown($style: a) {
	@if $style == a {
		position: relative;
		
		.dropdown-wrap {
			.dropdown-head {
				.dropdown-subject {
					margin: 0;
					cursor: pointer;

					&::before {
						content: attr(data-bui-tab-selected);
						display: flex;
						align-items: center;
						justify-content: space-between;

						position: relative;
						padding: 0 56rem 0 16rem;
						height: 56rem;

						@include font((outline: small-1x, size: 1.5)...);
						color: color(normal, 020);
	
						box-sizing: border-box;
						border-radius: 4rem 4rem 0 0;
						border: 1rem solid color(normal, 040);

						background-repeat: no-repeat;
						background-position: calc(100% - 16rem) 50%;
						background-size: 24rem;
						background-image: icon(chevron-under, color(normal, 020));
						
					}
					
					.dropdown-name {
						@include hidden;
					}
				}
			}

			.dropdown-body {
				display: none;
				position: absolute;
				z-index: 1;
				top: 100%;
				left: 0;
				right: 0;
				
				.navi-list {
					margin-top: 4rem;
					height: calc(48rem * 6);
					overflow-y: auto;
					@include overflow-scroll(default, dark);
					border-radius: 4rem;
					border: 1rem solid color(normal, 040);
					background-color: color(base, 000);
					box-shadow: 0 4rem 8rem 0 rgb(0 0 0 / 15%), 0 1rem 2rem 0 rgb(0 0 0 / 10%);

					.navi-item {
						display: flex;
						
						.navi-text {
							flex: 1 1 100%;
							display: flex;
							z-index: 2;
							padding: 12rem 16rem;
							@include font((outline: small-1x, size: 1.5)...);
							color: color(normal, 020);
							text-decoration: none;
							outline-offset: -1rem;
						}

						&:focus,
						&:hover {
							background-color: color(primary, 005);
						}

						&.current {
							.navi-text {
								background-color: color(primary, 005);
							}
						}
					}
				}
			}
		}
		&:focus-within {
			.dropdown-wrap {
				.dropdown-body {
					display: block;
				}
			}
		}
	}

	@if $style == b {
		.dropdown-wrap {
			.dropdown-head {
				.dropdown-subject {
					@include hidden;
				}
			}
			.dropdown-body {
				.navi-list {
					display: flex;
					flex-direction: column;
					row-gap: 8rem;

					.navi-item {
						display: flex;
						border-radius: 8rem;
			
						.navi-text {
							display: flex;
							flex: 1 1 100%;
							padding: 20rem 8rem;
							align-items: center;
							justify-content: center;
							text-decoration: none;
							@include font((outline: small-1x, size: 1.25, weight: medium)...);
							color: color(normal, 020);
							text-align: center;

							
						}

						&:focus-within {
							z-index: 2;
						}

						&.current {
							z-index: 1;
							overflow: hidden;
			
							.navi-text {
								color: color(accent, 000);
								@include font((weight: medium)...);
								background-color: color(accent, 010);
							}
						}
						
						&:not(.current) {
							border: 1rem solid color(accent, 010);
							&::before {
								border: 1rem solid color(base, 020);
							}
						}
					}
				}
			}
		}
	}
}

/**
 * @name		dropdown
 * @moudle		module-b
**/
.dropdown.module-b.style-a {
	@include dropdown(a);
}


.dropdown.module-b.style-b {
	@include dropdown(b);
}

.dropdown.module-b.style-d {
	// mobile
	@include respond-below(large-1x) {
		@include dropdown(a);
	}
	
	// laptop
	@include respond-above(large-1x) {
		@include dropdown(b);
	}
}