/**
 * form module-a
**/

// module-a outline
// @ $padding
// @ $line-height
// @ $font-size
// @ $font-weight
// @ $border-width
$form-module-a-outline: (
	'small-3x'		calc(14rem * 0.5) 14rem calc(14rem / 1.4) 400 1rem,
	'small-2x'		calc(16rem * 0.5) 16rem calc(16rem / 1.5) 400 1rem,
	'small-1x'		calc(20rem * 0.5) 20rem calc(20rem / 1.5) 400 1rem,
	'medium'		calc(20rem * 0.5) 20rem calc(20rem / 1.5) 400 1rem,
	'large-1x'		calc(22rem * 0.5) 22rem calc(22rem / 1.5) 400 1rem,
	'large-2x'		calc(22rem * 0.5) 22rem calc(22rem / 1.5) 400 1rem,
	'large-3x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-4x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-5x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-6x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
);

// 높이(textfield와 radio, textarea가 동일하지 않음);

.form.module-a {
	display: inline-flex;
	position: relative;

	.form-elem {
		position: relative;
		margin: 0;
		padding: 0;
		box-sizing: border-box; // textarea 적용안됨
		appearance: none;
	}

	&.radio {
		column-gap: 8rem;
		cursor: pointer;

		.form-elem {
			&::before {
				mask-image: icon(radio-off, color(normal, 100));
				cursor: pointer;
			}

			&:checked::before {
				mask-image: icon(radio-on, color(normal, 100));
			}
		}

		&.style-b {
			.form-elem {
				&::before {
					border-radius: 2rem;
				}
			}
		}
	}

	&.checkbox {
		column-gap: 8rem;
		cursor: pointer;

		.form-elem {			
			cursor: pointer;
			
			&::before {
				margin: 0 auto;
				border-radius: 4rem;
				border: 1rem solid color(base, 030);
				// mask-image: icon(check-off, color(normal, 100));
			}

			&:checked::before {
				border: 1rem solid color(accent, 010);
				// mask-image: icon(check-on, color(normal, 100));
			}
			&::after {
				content: '';
				display: block;
				position: absolute;
				top: 0;
				left: 0;
				background-color: color(normal, 000);
				mask-repeat: no-repeat;
				mask-position: center;
				mask-size: cover;
				mask-image: icon(check-on, color(normal, 000));
			}
			&:checked::after {
				background-color: color(normal, 000);
			}
		}
	}

	&.checkbox {
		.form-elem {
			display: inline-flex;
			justify-self: center;
			align-items: center;
			flex-shrink: 0;

			&::before {
				content: '';
				display: block;
				mask-repeat: no-repeat;
				mask-position: center;
				mask-size: cover;
				background-color: color(normal, 100);
				box-sizing: border-box;
			}
		}

		.form-text {
			display: block;
		}

		&.normal-00 {
			.form-text {
				color: color(normal, 000);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 000, 0.6);
				}
				&:checked::before {
					background-color: color(accent, 000);
				}
			}
		}

		&.accent-01 {
			.form-text {
				color: color(normal, 020);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 000);
				}
				&:checked::before {
					background-color: color(accent, 010);
				}
			}
		}

		&.accent-02 {
			.form-text {
				color: color(normal, 010);
			}
			.form-elem {
				&::before {
					background-color: color(base, 030);
				}
				&:checked::before {
					background-color: color(accent, 020);
				}
			}
		}
		
	}

	&.radio {
		.form-elem {
			flex-shrink: 0;

			&::before {
				content: '';
				display: block;
				mask-repeat: no-repeat;
				mask-position: center;
				mask-size: cover;
				background-color: color(normal, 100);
				box-sizing: border-box;
			}
		}

		.form-text {
			display: block;
		}

		&.normal-00 {
			.form-text {
				color: color(normal, 000);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 000, 0.6);
				}
				&:checked::before {
					background-color: color(accent, 000);
				}
			}
		}

		&.accent-01 {
			.form-text {
				color: color(normal, 020);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 030);
				}
				&:checked::before {
					background-color: color(accent, 010);
				}
			}
		}

		&.accent-02 {
			.form-text {
				color: color(normal, 010);
			}
			.form-elem {
				&::before {
					background-color: color(base, 030);
				}
				&:checked::before {
					background-color: color(accent, 020);
				}
			}
		}
		
	}
	
	&.switch {
		justify-content: center;
		align-items: center;
		column-gap: 8rem;

		.form-elem {
			padding: 2rem;
			width: 38rem;
			height: 20rem;
			border-radius: 38rem;
			background-color: color(normal, 040);
			transition: background-color 0.1s ease-out;
			cursor: pointer;

			&::after {
				content: '';
				display: block;
				position: absolute;
				top: 50%;
				transform: translateY(-50%);
				left: 2rem;
				width: 16rem;
				height: 16rem;
				box-shadow: -1px 0px 4px rgba(0, 0, 0, 0.24);
				border-radius: 8rem;
				background-size: auto 12rem;
				background-color: color(normal, 000);
				background-position: center;
				background-image: icon(close, color(normal, 030));
				transition: left 0.1s ease-out;
			}

			&:checked {
				background-color: color(accent, 010);
				&::after {
					left: calc(100% - 18rem);
					background-image: icon(check, color(accent, 010));
				}
				&::before {
					content: '';
					display: block;
					position: absolute;
					top: 50%;
					transform: translateY(-50%);
					left: 6rem;					
					color: color(base, 000);
				}
			}
		}

		.form-text {
			@include font((outline: small-3x, size: 1.4)...);
			color: color(normal, 020);
		}
	}

	// outline
	@each $name, $padding, $line-height, $font-size, $font-weight, $border-width in $form-module-a-outline {
		&.#{$name} {
			//radio outline
			&.radio {
				@include font((family: default)...);
				// column-gap: ((map-get($GLOBAL_OUTLINE, $name) / 1.5) / 4);

				.form-elem {
					width: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					background-size: map-get($GLOBAL_OUTLINE, $name) auto;

					&::before {
						width: map-get($GLOBAL_OUTLINE, $name);
						height: map-get($GLOBAL_OUTLINE, $name);
					}

					&::after {
						width: map-get($GLOBAL_OUTLINE, $name);
						height: map-get($GLOBAL_OUTLINE, $name);
						mask-size: map-get($GLOBAL_OUTLINE, $name)*0.8;

					}
				}
				.form-text {
					font-size: $line-height;
					line-height: map-get($GLOBAL_OUTLINE, $name);
					// font-size: map-get($GLOBAL_OUTLINE, $name) / 1.5;
				}
			}

			// checkbox outline
			&.checkbox {
				@include font((family: default)...);
				// column-gap: ((map-get($GLOBAL_OUTLINE, $name) / 1.5) / 4);

				.form-elem {
					width: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					background-size: map-get($GLOBAL_OUTLINE, $name) auto;

					&::before {
						width: map-get($GLOBAL_OUTLINE, $name)*0.92;
						height: map-get($GLOBAL_OUTLINE, $name)*0.92;
					}

					&::after {
						width: map-get($GLOBAL_OUTLINE, $name)*0.92;
						height: map-get($GLOBAL_OUTLINE, $name)*0.92;
						mask-size: map-get($GLOBAL_OUTLINE, $name)*0.92;
						top:  calc(50% - map-get($GLOBAL_OUTLINE, $name)*0.92/2);
						left:  calc(50% - map-get($GLOBAL_OUTLINE, $name)*0.92/2);

					}
				}
				.form-text {
					font-size: $line-height;
					line-height: map-get($GLOBAL_OUTLINE, $name);
					// font-size: map-get($GLOBAL_OUTLINE, $name) / 1.5;
				}
			}
		}
	}
}


