// module-b outline

// @ $padding
// @ $line-height
// @ $font-size
// @ $font-weight
// @ $border-width

$form-module-b-outline: (
	'small-1x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'medium'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-1x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-2x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-3x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-4x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-5x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-6x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
);

// 높이(textfield와 radio, textarea가 동일하지 않음);

.form.module-b {
	display: inline-flex;
	position: relative;

	.form-elem {
		position: relative;
		margin: 0;
		padding: 0;
		appearance: none;
		box-sizing: border-box; // textarea 적용안됨
		@include font((family: default)...);

		&[type=search] {
			&::-webkit-search-decoration,
			&::-webkit-search-cancel-button,
			&::-webkit-search-results-button,
			&::-webkit-search-results-decoration{
				display:none;
			}
		}

		&[type=time] {
			&::-webkit-inner-spin-button,
			&::-webkit-calendar-picker-indicator{
				display:none;
			}
		}
	}
	// style
	&.style-b {
		.form-elem {
			border-radius: 4rem;
		}
	}

	// cancel button
	&.select,
	&.search,
	&.timepicker,
	&[class*="url-"],
	&.colorpicker,
	&.datepicker,
	&.date,
	&.textfield {
		.form-elem {
			flex: 1 1 100%;
			width: 100%;
			border-style: solid;
			outline-color: color(accent, 010);
		}

		.form-util,
		.form-func {
			display: flex;
			align-items: center;
			position: absolute;

			top: 0;
			right: 0;
			bottom: 0;
			pointer-events: none;

			.form-cancel {
				display: none;
				background-repeat: no-repeat;
				background-position: center;
				background-size: cover;
			}

			.form-color {
				display: flex;
				border-radius: 100%;
				border: 1rem solid color(normal, 050);
				box-sizing: border-box;
			}
		}
	}

	//date
	.form-elem[type=date]::-webkit-inner-spin-button,
	.form-elem[type=date]::-webkit-calendar-picker-indicator {
		display: none;
		-webkit-appearance: none;
	}

	//file
	// [type=file] {
	// 	text-indent: 0 !important;
	// 	padding-left: 19.2rem !important;
	// }

	[type=file]::file-selector-button {
		display: none;
	}

	// input[type="file"]::-webkit-file-upload-button {
	// 	background-color: red;
	// }

	&:focus-within.typed,
	&:hover.typed {
		.form-util,
		.form-func {
			.form-cancel {
				display: block;
				mask-repeat: no-repeat;
				mask-position: center;
				mask-image: icon(circle-delete, color(base, 030));
			}
		}
	}

	// select
	&.select,
	&.search,
	&.timepicker {
		&::after {
			content: '';
			display: block;
			position: absolute;
			top: 0;
			right: 0;
			bottom: 0;
			pointer-events: none;
			background-repeat: no-repeat;
			background-position: center;
			background-size: cover;
		}
	}

	//url
	&[class*="url-"] {
		&.typed {
			.form-elem {
				text-decoration: underline;
			}
		}

		&::after {
			content: '';
			display: block;
			position: absolute;
			top: 0;
			left: 0;
			bottom: 0;
			pointer-events: none;
			background-repeat: no-repeat;
			background-position: center;
			background-size: cover;
		}
	}

	&.textarea {
		.form-elem {
			flex: 1 1 100%;
			width: 100%;
			outline-color: color(accent, 010);
			border-style: solid;
			@include overflow-scroll(default, dark);
			resize: none;
		}
	}

	&.quantity {
		display: flex;

		input[type="number"]::-webkit-outer-spin-button,
		input[type="number"]::-webkit-inner-spin-button {
			-webkit-appearance: none;
			margin: 0;
		}

		.form-elem {
			order: 3;
			text-align: center;
			border: 1px solid #333;
			border-left: none;
			border-right: none;
		}

		.form-step-up,
		.form-step-down {
			border: 1px solid #333;
			box-sizing: border-box;
			display: flex;
			align-items: center;
			justify-content: center;
			cursor: default;
			@include font((family: default, size: small)...);

			&::after {
				content: '';
				display: block;
				pointer-events: none;
				background-repeat: no-repeat;
				background-position: center;
				background-size: cover;
			}

		}
		.form-step-up {
			order: 4;
		}
		.form-step-down {
			order: 2;
		}
	}

	&.timepicker {
		&:not(.active) {
			.tooltip.module-d {
				visibility: hidden;
				opacity: 0;
				transform: translateY(10rem);
			}
		}
		.tooltip.module-d {
			position: absolute;
			top: calc(100% + 12rem);
			left: 0;
			z-index: 1;
			transition: visibility 0.25s ease, opacity 0.25s ease, transform 0.25s ease;
			}
	}

	// colorpicker
	&.colorpicker {
		&::before {
			content: attr(data-bui-form-value);
			display: flex;
			align-items: center;
			position: absolute;
			z-index: 1;
			top: 0;
			right: 0;
			bottom: 0;
			left: 0;
			box-sizing: border-box;
			pointer-events: none;
		}

		&::after {
			content: '';
			display: block;
			position: absolute;
			border-radius: 50%;
			box-shadow: inset 0 0 0 1rem rgba(0,0,0,0.25);
			background-color: var(--bui-form-value);
			pointer-events: none;
		}

		.form-elem::-moz-color-swatch {
			display: none;
		}

		.form-elem::-webkit-color-swatch-wrapper {
			display: none;
		}
	}

	&.datepicker,
	&.date {
		.form-elem {
			text-overflow: ellipsis;
			background-repeat: no-repeat;
		}
	}
	
	&.radio,
	&.checkbox {
		display: inline-flex;
		vertical-align: top;
		position: relative;
		
		.form-elem {
			display: block;
			position: absolute;
			top: 0;
			right: 0;
			bottom: 0;
			left: 0;
			margin: 0;
			width: 100%;
			height: 100%;
			cursor: pointer;

			&:checked {
				&+.form-text {
					background-color: color(primary, 005);
					border-color: color(accent, 010);
					color: color(accent, 010);
				}
			}
		}

		.form-text {
			display: flex;
			align-items: center;
			justify-content: center;
			width: 100%;
			// min-width: 128rem;
			background-color: color(normal, 000);
			border: 1rem solid color(normal, 040);
			box-sizing: border-box;
			@include font((outline: small-2x, size: 1.5)...);			
			color: color(base, 060);
		}

		&.style-b {
			.form-text {
				border-radius: 4rem;
			}
		}

		&[class*="attr-"] {
			.form-elem {
				&:checked {
					&+.form-text {
						&::before {
							background-color: color(accent, 010);
						}
					}
				}
			}

			.form-text {
				display: flex;
				column-gap: 4rem;
				background-color: color(base, 005);

				&::before {
					content: '';
					flex-shrink: 0;
					display: block;
					width: 24rem;
					height: 24rem;
					background-repeat: no-repeat;
					background-position: center;
					background-size: auto 100%;
					background-color: color(normal, 040);
					mask-repeat: no-repeat;
					mask-size: cover;
					mask-position: center;
				}
			}		
		}
	}

	&.radio {
		&.attr-check {
			.form-text {
				&::before {
					mask-image: icon(radio-on-small, color(base, 060));
				}
			}
		}
	}

	&.checkbox {
		&.attr-check {
			.form-text {
				&::before {
					mask-image: icon(check, color(base, 060));
				}
			}
		}
	}

	// outline
	@each $name, $padding, $line-height, $font-size, $font-weight, $border-width in $form-module-b-outline {
		&.#{$name} {
			// style
			&.style-c {
				.form-elem {
					border-radius: map-get($GLOBAL_OUTLINE, $name) * 0.5;
				}

				&.radio,
				&.checkbox {
					.form-text {
						border-radius: map-get($GLOBAL_OUTLINE, $name) * 0.5;
					}
				}
			}
			
			&.radio,
			&.checkbox {
				.form-text {
					padding: 0 $padding * 1.7;
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
				}

				&[class*="attr-"] {
					.form-text {
						padding: 0 $padding * 1.7  0 $padding * 1.34;
					}
				}
			}
		
			// textfield, select outline
			&.colorpicker,
			&.date,
			&.textfield {
				.form-elem {
					padding-right: map-get($GLOBAL_OUTLINE, $name) * 0.4;
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
					text-overflow: ellipsis;
					
					&:not([type=file]) {
						text-indent: map-get($GLOBAL_OUTLINE, $name) * 0.4;
					}

					&[type=file] {
						padding-left: map-get($GLOBAL_OUTLINE, $name) * 0.4;
						line-height: map-get($GLOBAL_OUTLINE, $name) - ($border-width * 2);
					}
				}

				.form-util,
				.form-func {
					padding: 0 $padding * 1.333;
					column-gap: calc(($line-height / 1.5) / 4);
					line-height: $line-height;
					font-size: $font-size;

					.form-cancel {
						width: $line-height;
						height: $line-height;
					}

					.form-down {
						width: $line-height;
						height: $line-height;
					}
				}
			}
			

			&.quantity {
				.form-elem {
					width: 3em;
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: calc($line-height/1.25);
					border-width: $border-width;
				}
				.form-step-up,
				.form-step-down {
					width: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
					&::after {
						width: $line-height;
						background-size: $line-height $line-height;
						height: $line-height;
					}
				}	
			}

			&.time {
				.form-elem {
					width: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
				}
			}
			
			// textfield, select background
			&.search,
			&.timepicker,
			&.select {
				.form-elem {
					padding-left: map-get($GLOBAL_OUTLINE, $name) * 0.4;
					padding-right: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
					text-overflow: ellipsis;
				}

				&::after {
					padding: 0 $padding;
					width: $line-height;
					background-size: $line-height $line-height;
				}
			}

			// textfield, select background
			&[class*="url-"] {
				.form-elem {
					padding-left: map-get($GLOBAL_OUTLINE, $name);
					padding-right: map-get($GLOBAL_OUTLINE, $name);
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
					text-overflow: ellipsis;
				}

				&::after {
					padding: 0 $padding;
					width: $line-height;
					background-size: $line-height $line-height;
				}

				.form-util,
				.form-func {
					padding: 0 $padding * 1.7;
					column-gap: calc(($line-height / 1.5) / 4);
					line-height: $line-height;
					font-size: $font-size;

					.form-cancel {
						width: $line-height;
						height: $line-height;
					}

					.form-down {
						width: $line-height;
						height: $line-height;
					}					
				}
			}

			// textarea
			&.textarea {
				display: flex;
				flex-direction: column;
				row-gap: 4rem;

				.form-elem {
					padding: calc($line-height * 0.6) map-get($GLOBAL_OUTLINE, $name) * 0.333;
					// padding: calc(($line-height - $font-size) / 2) $padding;
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
				}

				&.flex {
					flex: 1 1 100%;
				}

				.form-util,
				.form-func {
					display: flex;
					justify-content: flex-end;
					position: absolute;
					right: 0;
					bottom: 0;
					padding: 12rem 20rem;
					pointer-events: none;
					
					.form-count {
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 030);
						
						.value {
							color: color(normal, 030);
						}
					}
				}
			}

			// datepicker
			&.colorpicker {
				&::before {
					padding: 0 map-get($GLOBAL_OUTLINE, $name) * 0.36;
					line-height: $line-height;
					font-size: $font-size;
					@include font((family: default)...);
				}

				&::before,
				&::after {
					top: calc(50% - $line-height * 0.5);
					right: $padding * 1.333;
					width: $line-height;
					height: $line-height;
				}

				// .form-elem {
				// 	&::before,
				// 	&::after {
				// 		top: calc(50% - $line-height * 0.5);
				// 		right: $padding * 1.333;
				// 		width: $line-height;
				// 		height: $line-height;
				// 	}
				// }
			}

			// datepicker
			&.datepicker {
				.air-datepicker-cell {
					width: $line-height*1.33;
					height: $line-height*1.33;
				}

				.form-elem {
					line-height: $line-height;
					font-size: $font-size;
					@include font((family: default)...);
					border-width: $border-width;
					padding: 0 map-get($GLOBAL_OUTLINE, $name) * 0.36;
					height: map-get($GLOBAL_OUTLINE, $name);
					background-size: $line-height $line-height;
					background-position: calc(100% - ($line-height * 0.6)) 50%;
				}
			}
		}
	}

	// accent
	@each $accent-name in $form-module-b-accent {
		&.#{nth($accent-name, 1)} {        
			// @debug "divider offset: #{nth($accent-name, 1)}";
			@each $type-name, $color, $color-unit, $color-placeholder, $color-disabled, $border-color, $background-readonly, $background-disabled, $background-color in map-get($form-module-b-accent, nth($accent-name, 1)) {
				&.type-#{$type-name} {
					&.file,
					&.search,
					&.colorpicker,
					&.timepicker,
					&[class*="url-"],
					&.select,
					&.datepicker,
					&.date,
					&.textfield,
					&.textarea {	
						.form-text {
							color: $color;
						}

						.form-elem {
							color: $color;
							border-color: $border-color;
							background-color: $background-color;

							&::placeholder {
								color: $color-placeholder;
							}

							&:focus {
								background-color: color(base, 000);
								color: color(base, 090);

								&+.form-util,
								&+.form-func {
									.form-unit {
										color: color(base, 090);
									}
								}
							}
						}

						&.valid {
							.form-elem {
								// border-color: green;
							}
						}

						&.invalid {
							.form-elem {
								border-color:color(accent, 040);
							}
						}

						.form-util,
						.form-func {
							.form-cancel {
								background-color: color(base, 030);
							}

							.form-unit {
								color: $color-unit;
							}

							.form-color {
								color: transparent;
							}
						}
					}

					&.search {						
						&::after {
							background-image: icon(search, $color-unit);
						}
					}

					&.timepicker {						
						&::after {
							background-image: icon(time, $color-unit);
						}
					}

					&[class*="url-"] {			
						&.url-pc {
							&::after {
								background-image: icon(monitor, $color-unit);
							}		
						}

						&.url-mo {
							&::after {
								background-image: icon(mobile, $color-unit);
							}		
						}
					}

					&.select {						
						&::after {
							background-image: icon(chevron-down, $color-unit);
						}
					}
					
					&.quantity{
						.form-elem {
							color: $color;
							border-color: $border-color;
							background-color: $background-color;
						}
						.form-step-up {				
							border-color: $border-color;		
							&::after {
								background-image: icon(plus, $color-placeholder);
							}
						}
						.form-step-down {		
							border-color: $border-color;				
							&::after {
								background-image: icon(minus, $color-placeholder);
							}
						}
					}

					&.time {
						.form-elem {
							color: $color;
							border-color: $border-color;
							background-color: $background-color;
						}
					}
				
					//readonly
					&.search,
					&.timepicker,
					&[class*="url-"],
					&.datepicker,
					&.date,
					&.textfield,
					&.textarea {
						.form-elem[readonly] {
							color: $color;
							background-color: $background-readonly;

							&+.form-util,
							&+.form-func {
								.form-unit {
									color: $color-placeholder;
								}
							}
						}

						&.type-fill {
							.form-elem[readonly] {
								border-color: $background-readonly;
								color: $color-placeholder;
								// color: $color;
							}
						}
					}
					
					//disabled
					&.search,
					&.datepicker,
					&.date,
					&.timepicker,
					&[class*="url-"],
					&.select,
					&.textfield,
					&.textarea {
						.form-elem {
							&:disabled {
								color: $color-disabled;
								background-color: $background-disabled;

								&+.form-util,
								&+.form-func {
									.form-unit {
										color: $color-disabled;
									}
								}
							}	
						}
						&.type-fill {
							.form-elem {
								&:disabled {
									border-color: $background-disabled;
								}								
							}
						}
					}

					// datepicker
					&.datepicker {
						.form-elem {
							background-image: icon(calendar, $color);
						}

						&.type-fill {
							.form-elem:focus {
								background-image: icon(calendar, color(normal, 010));
							}
						}
					}
				}
			}
		}
	}
}

