// module-c outline

// @ $padding
// @ $line-height
// @ $font-size
// @ $font-weight
// @ $border-width

 $form-module-c-outline: (
	'small-1x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'medium'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-1x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-2x'		calc(20rem * 0.5) 20rem calc(20rem / 1.4) 400 1rem,
	'large-3x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-4x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-5x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
	'large-6x'		calc(24rem * 0.5) 24rem calc(24rem / 1.5) 400 1rem,
);

// 높이(textfield와 radio, textarea가 동일하지 않음);

.form.module-c {
	display: inline-flex;
	position: relative;

	.form-elem {
		position: relative;
		margin: 0;
		padding: 0;
		box-sizing: border-box; // textarea 적용안됨
		appearance: none;

	}

	&.radio {
		column-gap: 4rem;

		.form-elem {
			display: block;
			position: absolute;
			top: 0;
			right: 0;
			bottom: 0;
			left: 0;
			margin: 0;
			width: 100%;
			height: 100%;
			cursor: pointer;

			&:checked {
				~.form-text {
					border-color: color(accent, 010);
				}
			}
		}

		.form-text {
			display: flex;
			flex-shrink: 0;
			align-items: center;
			justify-content: center;
			width: 100%;
			// min-width: 128rem;
			background-color: color(normal, 000);
			border: 1rem solid color(normal, 040);
			box-sizing: border-box;
			@include font((outline: small-2x, size: 1.5)...);			
			color: color(base, 060);
		}
		
		&.style-b {
			.form-text {
				border-radius: 4rem;
			}
		}

		&.accent-01 {
			.form-text {
				color: color(normal, 020);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 020);
				}
				&:checked {
					&::before {
						background-color: color(normal, 020);
					}
					
				}
			}
		}

		&[class*="attr-"] {
			.form-elem {
				&:checked {
					~.form-text {
						&::after {
							mask-image: icon(chevron-up, color(normal, 020));
						}
					}
				}
			}

			.form-text {
				display: flex;
				column-gap: 4rem;

				&::after {
					content: '';
					flex-shrink: 0;
					display: block;
					width: 24rem;
					height: 24rem;
					background-repeat: no-repeat;
					background-position: center;
					background-size: auto 100%;
					background-color: color(normal, 020);
					mask-repeat: no-repeat;
					mask-size: cover;
					mask-position: center;
				}
			}
			
			&.attr-arrow {
				.form-text {
					&::after {
						mask-image: icon(chevron-down, color(normal, 020));
					}
				}				
			}
		}
	}

	&.checkbox {
		column-gap: 4rem;

		.form-elem {
			&::before {
				content: '';
				display: block;
				mask-repeat: no-repeat;
				mask-position: center;
				mask-size: cover;
				background-color: color(normal, 100);
				mask-image: icon(bullet-dot, color(normal, 100));
			}

			&:checked::before {
				mask-image: icon(check, color(normal, 100));
			}
		}

		.form-text {
			display: block;
		}

		&.style-b {
			.form-elem {
				&::before {
					border-radius: 2rem;
				}
			}
		}

		&.accent-01 {
			.form-text {
				color: color(normal, 020);
			}
			.form-elem {
				&::before {
					background-color: color(normal, 030);
				}
				&:checked {
					&::before {
						background-color: color(accent, 010);
					}

					~.form-text {
						@include font((weight: medium)...);
						color: color(accent, 010);
					}
				}
			}
		}
	}

	

	// outline
	@each $name, $padding, $line-height, $font-size, $font-weight, $border-width in $form-module-c-outline {
		&.#{$name} {
			&.style-c {
				.form-elem {
					border-radius: map-get($GLOBAL_OUTLINE, $name) * 0.5;
				}

				&.radio,
				&.checkbox {
					.form-text {
						border-radius: map-get($GLOBAL_OUTLINE, $name) * 0.5;
					}
				}
			}

			// radio outline
			&.radio {
				@include font((family: default)...);
				// column-gap: ((map-get($GLOBAL_OUTLINE, $name) / 1.5) / 4);

				.form-elem {
					width: $line-height;
					height: $line-height;
					background-size: map-get($GLOBAL_OUTLINE, $name) auto;

					&::before {
						width: $line-height;
						height: $line-height;
					}
				}

				.form-text {
					padding: 0 $padding * 1.7;
					height: map-get($GLOBAL_OUTLINE, $name);
					line-height: $line-height;
					font-size: $font-size;
					border-width: $border-width;
				}

				&[class*="attr-"] {
					.form-text {
						padding: 0 $padding * 1.34  0 $padding * 1.7;
					}
				}
			}

			// checkbox outline
			&.checkbox {
				@include font((family: default)...);
				// column-gap: ((map-get($GLOBAL_OUTLINE, $name) / 1.5) / 4);

				.form-elem {
					width: $line-height;
					height: $line-height;
					background-size: map-get($GLOBAL_OUTLINE, $name) auto;

					&::before {
						width: $line-height;
						height: $line-height;
					}
				}
				.form-text {
					line-height: $line-height;
					font-size: $font-size;
				}
			}
		}
	}
}

/**
 * dropdown module-c
**/
.dropdown.module-c {

	&:not(.active) {
		.dropdown-wrap {
			.dropdown-head {
				.dropdown-subject {
					border: 1rem solid color(normal, 040);

					&::after {
						mask-image: icon(chevron-down, color(normal, 010));
					}
				}
			}
			.dropdown-body {
				visibility: hidden;
				opacity: 0;
			}
		}
	}

	&.active {}

	.dropdown-wrap {
		position: relative;

		.dropdown-head {
			.dropdown-subject {
				display: flex;
				column-gap: 4rem;
				align-items: center;
				margin: 0;
				height: 32rem;
				padding: 0rem 10rem 0rem 12rem;
				background-color: color(normal, 000);
				box-sizing: border-box;
				border: 1rem solid color(accent, 010);
				@include font((outline: small-3x, size: 1.4)...);
				color: color(normal, 010);

				&::before {
					flex: 1 1 100%;
					content: attr(data-bui-dropdown-selected);
					display: flex;
					align-items: center;
				}

				&::after {
					content: '';
					display: block;
					flex-shrink: 0;
					width: 20rem;
					height: 20rem;
					background-color: color(normal, 010);
					mask-repeat: no-repeat;
					mask-position: center;
					mask-size: cover;
					mask-image: icon(chevron-up, color(normal, 010));
				}


				.dropdown-name {
					@include hidden;
				}
			}
		}

		.dropdown-body {
			position: absolute;
			top: calc(100% + 4rem);
			right: 0;
			left: 0;
			z-index: 2;
			padding: 8rem;
			background-color: color(normal, 000);
			box-sizing: border-box;
			border-radius: 4rem;
			box-shadow: 0px 0px 16px rgba(0, 0, 0, 0.08);

			.navi-list {
				.navi-item {
					display: flex;
					flex-direction: column;

					.navi-name {
						padding: 6rem 8rem;
						border-radius: 4rem;
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 010);
						text-decoration: none;
						
						&:hover {
							background-color: color(base, 005);
						}
					}
				}
			}
		}
	}

	&.style-b {
		.dropdown-wrap {
			.dropdown-head {
				.dropdown-subject {
					border-radius: 4rem;

					&::before {
					}
				}
			}
		}
	}
}

