ul.posts-list {
	margin: 0;
	padding: 0;
	list-style: none;
}

/**
 * @type		component
 * @name		posts-display
 * @moudle		module-a
**/
.posts-display.module-a {
	>.pagination {
		margin-top: 56rem;
	}
}

/**
 * @type		component
 * @name		posts-display
 * @moudle		module-b
**/
@mixin posts-display-inform {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	column-gap: 8rem;

	.posts-prop {
		display: flex;

		.data-list {
			display: flex;

			.data-item {
				display: flex;

				.head {
					@include hidden;
				}
				.body {
					display: flex;
					flex-wrap: wrap;
					column-gap: 8rem;

					.mark.module-a {
						min-width: 72rem;
					}
				}
			}
		}
	}
	
	.posts-info {
		display: flex;
		align-items: center;
		
		.data-list {
			display: flex;
			column-gap: 12rem;

			.data-item {
				display: flex;
				column-gap: 8rem;
				position: relative;

				+.data-item {
					padding-left: 12rem;

					&::before {
						content: '';
						display: block;
						position: absolute;
						top: calc(50% - 16rem/2);
						left: 0;
						width: 1rem;
						height: 16rem;
						background-color: color(normal, 040);
					}
				}
				
				.head {
					@include font((outline: small-3x, size: 1.4, weight: black)...);
					color: color(normal, 010);
				}
				.body {
					@include font((outline: small-3x, size: 1.4)...);
					color: color(normal, 020);
				}

				&.period {
					.head {
						@include hidden;
					}
				}
				
			}
		}
		+.posts-head {
			margin-top: 16rem;
		}
	}

	.posts-head {
		flex: 1 1 100%;
		display: flex;

		.posts-subject {
			margin: 0;

			.posts-name {
				@include font((outline: small-1x, size: 1.3, weight: bold)...);
				color: color(normal, 010);
			}
		}
		
		+.posts-data {
			margin-top: 4rem;
			
		}
	}

	.posts-data {
		flex: 1 1 100%;
		display: flex;

		.data-list {
			display: flex;

			.data-item {
				.head {
					@include hidden;
				}

				.body {
					@include font((outline: small-3x, size: 1.4)...);
					color: color(normal, 030);
				}
			}
		}
	}
}

.posts-display.module-b {
	display: flex;
	align-items: center;
	
	.posts-wrap {
		flex: 1 1 100%;

		.posts-inform {
			@include posts-display-inform;
		}
	}

	.posts-util {
		display: flex;
		flex-shrink: 0;

		.button-area {
			flex: 1 1 100%;
			display: flex;
			column-gap: 8rem;
			
			.btn {
				min-width: 104rem;
				
				&.flex {
					flex: 1 1 100%;
				}
				
			}
		}
	}

	&.style-b {
		flex-direction: column;
		row-gap: 32rem;
		align-items: stretch;

		.posts-util {
			flex: 1 1 100%;
		}
	}
}

