/**
 * @type		component
 * @name		data-uploader
 * @moudle		module-a
**/
.data-uploader.module-a {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	margin-bottom: 56rem;

	.data-form {
		flex: 1 1 100%;
		display: flex;
		justify-content: center;
		padding: 36rem;
		background-color: color(base, 005);

		.submit-form {
			flex: 1 1 100%;
			max-width: 960rem;


			.form-util {
				.button-display {
					.button-area {
						.btn {
							min-width: 112rem;
						}
					}
				}
			}
		}
	}
}

/**
 * @type		component
 * @name		data-finder
 * @moudle		module-a
**/
.data-finder.module-a {
	display: flex;
	flex-wrap: wrap;
	// row-gap: 56rem;
	align-items: center;

	.data-form {
		flex: 1 1 100%;
		display: flex;
		justify-content: center;
		padding: 36rem;
		background-color: color(base, 005);

		.submit-form {
			flex: 1 1 100%;
			max-width: 960rem;

			.form-list {
				.form-item {
					.form-body {
						.form-area {
							.form {
								&.datepicker {
									width: 160rem;
								}
							}
						}
					}
				}
			}

			.form-util {
				.button-display {
					.button-area {
						.btn {
							min-width: 112rem;

							&.symbol-ltr-chevron-down.active {
								.btn-text {
									&::before {
										transform: rotate(180deg);
									}
								}
							}
						}
					}
				}
			}
		}
	}

	.data-filter {
		display: flex;
		flex-direction: column;
		flex: 1 1 100%;

		&:not(.active) {
			>.submit-form {
				display: none;
			}
		}
		
		>.submit-form {
			background-color: color(normal, 050);

			>.form-list {
				display: flex;
				flex-direction: column;
				row-gap: 16rem;
				padding: 16rem 40rem;

				.form-item {
					+.form-item {
						padding-top: 16rem;
						border-top: 1rem solid color(base, 020);
					}
					.form-wrap {
						.form-head {}
						.form-body {
							.option-list {
								margin: 0;
								
								.option-item {									
									>.form {
										.form-text {
											.em {
												font-weight: 500;
											}
										}
									}
								}
							}
							.submit-form {
								.form-list {
									.form-item {
										.form-wrap {
											column-gap: 12rem;
											
											.form-head {
												width: auto;

												.form-subject {
													.form-name {
														@include font((outline: small-3x, size: 1.4)...);
													}
												}
											}

											.form-body {
												.form-area {
													display: flex;

													.btn {
														flex: auto 0 0;
													}
												}
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}

		>.filter-side {
			flex: 1 1 100%;
			display: flex;
			justify-content: space-between;
			padding: 12rem 40rem;
			background-color: color(base, 005);

			>.option-list {
				column-gap: 4rem;
				row-gap: 4rem;

				.option-item {
					.mark {
						display: inline-flex;
						column-gap: 4rem;
			
						.btn {
							&::before {
								content: '';
								display: block;
								width: 20rem;
								height: 20rem;
								background-color: color(primary, 040);
								mask-size: cover;
								mask-position: center;
								mask-repeat: no-repeat;
							}
			
							&.delete {
								&::before {
									mask-image: icon(close, color(base, 100));
								}
			
								.btn-text {
									@include hidden;
								}
							}
						}
					}
				}

				~.button-display {
					flex-shrink: 0;
					position: relative;
					margin-left: 20rem;
					padding-left: 20rem;
		
					&::before {
						content: '';
						display: block;
						position: absolute;
						top: calc((32rem - 20rem)/2);
						left: 0;
						width: 1rem;
						height: 20rem;
						background-color: color(base, 020);
					}

					.button-area {
						display: flex;
						
					}
				}
			}
		}
	}	

	.data-info {
		display: flex;
		align-items: center;
		margin-top: 64rem;

		.data-list {
			.data-item {
				@include font((outline: small-2x, size: 1.5)...);
				color: color(normal, 030);

				.head {
					@include hidden();
				}
				.body {
				}
			}
		}

		~.data-func {
			flex: 0;
		}
	}

	.data-func {
		flex: 1 1 100%;
		display: flex;
		justify-content: flex-end;
		margin-top: 64rem;

		.button-area {
			display: flex;
			column-gap: 8rem;

			+.data-sort {
				margin-left: 8rem;
			}
		}

		.data-sort {
			display: flex;
			column-gap: 8rem;

			.dropdown.module-c {
				min-width: 130rem;
			}

			+.button-area {
				position: relative;
				margin-left: 12rem;
				padding-left: 12rem;
				
				&::before {
					content: '';
					position: absolute;
					top: 50%;
					left: 0;
					width: 1rem;
					height: 16rem;
					margin-top: -8rem;
					background-color: color(normal, 040);
				}
			}
		}
	}
	
	.data-type {
		margin-top: 56rem;

		~.data-func {
			flex: 0;
		}
	}

	&.type-b {
		justify-content: flex-end;
	}

	&.type-c {
		justify-content: center;
	}

	&.type-d {
		justify-content: space-between;
	}

	&.data-search {
		.data-form {
			>.submit-form {
				.form.module-a {
					>.form-list {
						>.form-item {
							>.form-wrap {
								.form-head {
								}
								.form-body {}
							}
						}
					}
				}
			}
		}
	}
	&.unified-search {		
	}
}

/**
 * @type		component
 * @name		data-finder
 * @moudle		module-b
**/
.data-finder.module-b {
	display: flex;
	align-items: center;
	
	.data-type {}

	.data-form {
		.submit-form {
			.form-list {
				.form-item {
					.form-body {
