	}
}

/**
* @type			component
* @name			pagination
* @moudle		module-a
*/
.pagination {
	display:block;
}

.pagination.module-a.style-a {
	display: flex;
	column-gap: 12rem;

	&.type-b {
		justify-content: flex-end;
	}

	&.type-c {
		justify-content: center;
	}

	.pagination-util .btn,
	.pagination-list .pagination-item {
		display: flex;
		justify-content: center;
		align-items: center;
		text-align: center;
		width: 32rem;
		height: 32rem;
		color: color(normal, 030);
		box-sizing: border-box;
		@include font((outline: small-2x, size: 1.5)...);
	}

	.pagination-util {
		display: flex;

		.button-area {
			display: flex;
			align-items: center;
			
			.btn {
				overflow: hidden;
				background-color: #fff;
				background-repeat: no-repeat;
				background-position: center;
				background-size: 32rem;
				border-radius: 4rem;
				text-decoration: none;

				&:hover {
					background-color: rgba(0,0,0,.04);
				}

				&:focus {
					position: relative;
					background-color: rgba(0,0,0,.08);
				}

				.btn-text {
					// position: relative;
					// z-index: -1;
					@include hidden;
				}

				&.disabled {
					pointer-events: none;

					&.first {background-image: icon(double-chevron-left, color(base, 060));}
					&.prev {background-image: icon(chevron-left, color(base, 060));}
					&.next {background-image: icon(chevron-right, color(base, 060));}
					&.last {background-image: icon(double-chevron-right, color(base, 060));}
				}
				
				&.first {background-image: icon(double-chevron-left, color(base, 060));}
				&.prev {background-image: icon(chevron-left, color(base, 060));}
				&.next {background-image: icon(chevron-right, color(base, 060));}
				&.last {background-image: icon(double-chevron-right, color(base, 060));}
			}
		}
	}

	.pagination-list {
		display: flex;
		column-gap: 12rem;

		.pagination-item {			
			&:not(:hover):not(:focus) {
				text-decoration: none;
			}

			&.current {
				@include font((weight: medium)...);
				color: color(accent, 010);
				text-decoration: none;
			}

		}
	}
}