@import '_variables';

/**
 * list style
**/

p.data-list,
p.data-item {
	margin: 0;
}

ul.navi-list,
ol.order-list,
ul.data-list {
	margin: 0;
	padding: 0;
	list-style: none;
}

.data-list {
	>li.data-item {
		a.em {
			text-decoration: underline;
		}
	}
}

$list-a-accent: (
	'normal-00' color(normal, 100) color(normal, 100),
	'normal-01' color(normal, 010) color(normal, 010),
	'normal-02' color(normal, 020) color(normal, 020),
	'normal-03' color(normal, 030) color(normal, 030),
	'normal-04' color(normal, 040) color(normal, 040),
	'normal-05' color(normal, 050) color(normal, 050),
	'normal-06' color(normal, 020) color(normal, 050),
	'accent-01' color(accent, 010) color(accent, 010),
	'accent-02' color(accent, 020) color(accent, 020),
	'accent-03' color(accent, 030) color(accent, 030),
	'accent-04' color(accent, 040) color(accent, 040),
	'accent-05' color(normal, 010) color(primary, 005),
);

$list-a-outline: (
	'small-7x'	map-get($GLOBAL_OUTLINE, 'small-7x'),
	'small-6x'	map-get($GLOBAL_OUTLINE, 'small-6x'),
	'small-5x'	map-get($GLOBAL_OUTLINE, 'small-5x'),
	'small-4x'	map-get($GLOBAL_OUTLINE, 'small-4x'),
	'small-3x'	map-get($GLOBAL_OUTLINE, 'small-3x'),
	'small-2x'	map-get($GLOBAL_OUTLINE, 'small-2x'),
	'small-1x'	map-get($GLOBAL_OUTLINE, 'small-1x'),
	'medium'	map-get($GLOBAL_OUTLINE, 'medium'),
	'large-1x'	map-get($GLOBAL_OUTLINE, 'large-1x'),
	'large-2x'	map-get($GLOBAL_OUTLINE, 'large-2x'),
	'large-5x'	map-get($GLOBAL_OUTLINE, 'large-5x'),
	'large-6x'	map-get($GLOBAL_OUTLINE, 'large-6x'),
	'large-7x'	map-get($GLOBAL_OUTLINE, 'large-7x'),
	'large-8x'	map-get($GLOBAL_OUTLINE, 'large-8x'),
	'large-9x'	map-get($GLOBAL_OUTLINE, 'large-9x'),
	'large-10x'	map-get($GLOBAL_OUTLINE, 'large-10x'),
	'large-11x'	map-get($GLOBAL_OUTLINE, 'large-11x'),
);

.data-list.module-a {
	flex-direction: column;

	.data-item {
		position: relative;
	}	

	&.type-a {.data-item::before {background-image: icon(bullet-dash, color(base, 100));}}
	&.type-b {.data-item::before {background-image: icon(bullet-square,color(base, 100));}}
	&.type-c {.data-item::before {background-image: icon(bullet-dot, color(base, 100));}}
	&.type-d {.data-item::before {background-image: icon(bullet-star, color(base, 100));}}
	
	&[class*=type-] {
		.data-item {
			&::before {
				content: '';
				display: flex;
				justify-content: center;
				align-items: center;

				position: absolute;
				top: 0;
				left: 0;
				text-align: center;
				background-repeat: no-repeat;
				background-position: center;
				background-size: cover;
			}
		}
	}

	// accent
	@each $name, $text-color, $util-color in $list-a-accent {
		&.#{$name} {
			color: $text-color;
			
			&[class*=type-] {
				.data-item {
					&::before {
						// background-color: $text-color;
					}
				}
			}
		}
	}

	// outline
	@each $name, $line-height in $list-a-outline {
		&.#{$name} {
			line-height: $line-height;
			font-size: calc($line-height / 1.5);

			.data-item {
				>.data-list.module-a {
					margin-top: calc($line-height / 4)
				}
			}
			
			&[class*=type-] {
				.data-item {
					padding-left: $line-height;

					&::before {
						width: $line-height;
						height: $line-height;
					}
				}
			}
		}
	}
}

.data-list.module-b {
	flex-direction: column;

	.data-item {
		position: relative;
	}	

	&.type-a {
		.data-item::before {
			mask-image: icon(circle-info, color(base, 100));
		}
	}
	
	&[class*=type-] {
		.data-item {
			&::before {
				content: '';
				display: flex;
				justify-content: center;
				align-items: center;
				position: absolute;
				top: 0;
				left: 0;
				text-align: center;
				mask-repeat: no-repeat;
				mask-position: center;
				mask-size: cover;
			}
		}
	}

	// accent
	@each $name, $text-color, $util-color in $list-a-accent {
		&.#{$name} {
			color: $text-color;
			
			&[class*=type-] {
				.data-item {
					&::before {
						background-color: $text-color;
					}
				}
			}
		}
	}

	// outline
	@each $name, $line-height in $list-a-outline {
		&.#{$name} {
			line-height: $line-height;
			font-size: calc($line-height / 1.4);

			.data-item {
				>.data-list.module-a {
					margin-top: calc($line-height / 4)
				}
			}
			
			&[class*=type-] {
				.data-item {
					padding-left: $line-height * 1.2;

					&::before {
						width: $line-height;
						height: $line-height;
					}
				}
			}
		}
	}
}

/**
 * @name		order-list
 * @moudle		module-a
**/
 .order-list.module-a {
	counter-reset: order-count;

	>.order-item {
		position: relative;
		display: flex;
		counter-increment: order-count;		

		&::before {
			content: counter(order-count) ". ";
			display: block;
			position: absolute;
			left: 0;
			padding: 0;
			text-align: right;
			transform: translate(0, -50%);
		}
	}

	&.style-b {
		>.order-item {	
			&::before {
				content: counter(order-count) ") ";
				display: block;
			}
		}
	}

	&.style-c {
		>.order-item {	
			&::before {
				content: "("counter(order-count)") ";
				display: block;
				text-align: left;
			}
		}
	}

	&.type-b{
		>.order-item {
			&::before {
				text-align: right;
			}
		}
	}

	&.type-c{
		>.order-item {
			&::before {
				text-align: center;
			}
		}
	}
	

	// accent
	@each $name, $text-color, $util-color in $list-a-accent {
		&.#{$name} {
			color: $text-color;
			
			&[class*=type-] {
				.order-item {
					&::before {
						// background-color: $util-color;
					}
				}
			}
		}
	}

	// outline
	@each $name, $line-height in $list-a-outline {
		&.#{$name} {
			line-height: $line-height;
			font-size: calc($line-height / 1.5);

			.order-item {
				>.data-list.module-a {
					margin-top: calc($line-height / 4)
				}
			}
			
			&[class*=type-] {
				.order-item {
					padding-left: $line-height * 1.2;

					&::before {
						width: $line-height;
						height: $line-height;
						top: $line-height * 0.5;
					}
				}
			}
		}
	}

}

/**
 * @name		order-list
 * @moudle		module-b
**/
.order-list.module-b {
	counter-reset: order-count;

	>.order-item {
		position: relative;
		counter-increment: order-count;

		&::before {
			content: counter(order-count);
			display: block;
			position: absolute;
			left: 2rem;
			text-align: center;
			color: color(normal, 010);
			border-radius: 50%;
			transform: translate(0, -50%);
		}

		>.order-wrap {
			display: flex;
			flex-direction: column;
			row-gap: 8rem;

			>.order-head {
				@include font((outline: small-1x, size: 1.5, weight: semi-bold)...);
			}

			>.order-body {
				>.para {
					@include font((outline: small-1x, size: 1.5)...);
				}
				>.data-list.module-a {
					margin-top: 12rem;
				}
				
			}
		}
	}

	// accent
	@each $name, $text-color, $util-color in $list-a-accent {
		&.#{$name} {
			color: $text-color;
			
			&[class*=type-] {
				.order-item {
					&::before {
						background-color: $util-color;
					}
				}
			}
		}
	}

	// outline
	@each $name, $line-height in $list-a-outline {
		&.#{$name} {
			line-height: $line-height;
			font-size: calc($line-height / 1.5);

			.order-item {
				>.data-list.module-a {
					margin-top: calc($line-height / 4)
				}
			}
			
			>&[class*=type-] {
				>.order-item {
					padding-left: $line-height * 1.165;

					&::before {
						width: $line-height* 0.75;
						height: $line-height* 0.75;
						top: $line-height * 0.5;
						line-height: $line-height * 0.75;
						font-size : calc(($line-height*0.75) / 2);
						font-weight: 600;
					}
				}
			}
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-a
**/
.data-display.module-a[class*=type-] {
	>.data-list {
		.data-item {
			&:first-child {
				border-top: 0;
			}
			.data-wrap {
				display: flex;

				.data-head {
					.data-subject {
					}
					.data-summary {
					}
				}
				.data-body {

					.data-list {
					}
				}
			}
		}
	}
	
	&.type-a {
		>.data-list {	
			.data-item {	
				.data-wrap {
					display: flex;
	
					.data-head {	
						.data-subject {
						}
					}
					.data-body {
						flex: 1 1 100%;
						padding: 20rem;	
					}
				}
				.data-display {
					.data-list {
						.data-item {
							.data-wrap {
								.data-head {
								}
							}
						}
					}
				}
			}
		}
	}

	&.type-b {
		.data-list {
			.data-item {
				.data-wrap {
					justify-content: space-between;		
				}
				.data-display {
					.data-list {						
						justify-content: space-between;		
						.data-item {
							.data-wrap {
								.data-head {
								}
							}
						}
					}
				}
			}
			
		}
	}
	&.type-c {
		.data-list {
			.data-item {
				.data-wrap {
					flex-direction: column;					
				}
				.data-display {
					.data-list {						
						flex-direction: column;
						.data-item {
							.data-wrap {
								.data-head {
								}
							}
						}
					}
				}
			}
			
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-b
**/
.data-display.module-b {
	>.data-list {
		display: flex;
		flex-direction: column;
		row-gap: 32rem;

		>.data-item {			
			>.data-wrap {
				display: flex;
				align-items: flex-start;
				column-gap: 8rem;

				>.data-head {
					flex-shrink: 0;
					min-width: 128rem;
					max-width: 128rem;

					>.data-subject {
						display: flex;
						margin: 0;
						@include font((outline: small-2x, size: 1.5, weight: bold)...);
						color: color(normal, 010);
					}
				}

				>.data-body {
					display: flex;
					flex-direction: column;
					row-gap: 8rem;
					flex: 1 1 100%;
					@include font((outline: small-2x, size: 1.5)...);
					color: color(normal, 010);
					
					&:has(.heading-box.module-a) {
						row-gap: 16rem;
					}

					&:has(.message-preview-slides) {
						width: calc(100% - 128rem - 16rem)
					}

					>.data-list {
						>.data-item {
							>.data-wrap {
								display: flex;
								flex-direction: column;
								row-gap: 8rem;

								>.data-head {
									.data-subject {
										margin: 0;
										@include font((outline: small-2x, size: 1.5, weight: medium)...);
										color: color(normal, 010);

										.data-name {}
									}
								}
								>.data-body {}
							}
						}
					}

					>.data-display {						
						+.para {
							margin-top: 16rem;
						}
					}

					>.para {
						>strong.em {
							@include font((weight: medium)...);
						}
					}
				}
			}
		}
	}

	&.style-b {
		>.data-list {
			>.data-item {
				
				~.data-item {
					padding-top: 32rem;
					border-top: 1rem solid color(normal, 050);
				}
			}
		}
	}

	&.type-b {
		.data-list {
			.data-item {
				.data-wrap {
					justify-content: space-between;

					.data-head {}
					.data-body {}
				}
			}
			}
	}
	&.type-c {
		.data-list {
			.data-item {
				.data-wrap {
					flex-direction: column;

					.data-head {}
					.data-body {}
				}
			}
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-c
**/
.data-display.module-c {
	>.data-caption {
		@include hidden;
	}

	>.data-list {
		display: flex;
		flex-direction: column;
		row-gap: 12rem;

		>.data-item {
			position: relative;

			>.data-wrap {
				display: flex;
				column-gap: 8rem;
				row-gap: 4rem;

				>.data-head {
					.data-subject {
						min-width: 64rem;
						margin: 0;
						@include font((outline: small-3x, size: 1.4, weight: medium)...);
						color: color(normal, 010);
					}
				}

				>.data-body {
					overflow: hidden;
					display: flex;
					flex-direction: column;
					row-gap: 4rem;
					@include font((outline: small-3x, size: 1.4)...);
					color: color(normal, 010);
				}
			}
		}
	}

	>.data-list {
		display: flex;
		flex-wrap: wrap;
		flex-direction: column;
		row-gap: 12rem;
	}

	&.style-b {
		>.data-list {
			padding: 12rem 20rem;
			background-color: color(base, 005);
		}

		>.data-util {
			padding: 0 20rem;
			background-color: color(base, 005);
			
			.button-area {
				display: flex;
				justify-content: center;
				padding: 12rem 0;
				border-top: 1rem solid color(base, 010);
	
				.btn {
					flex: 1 1 100%;
				}
			}
		}
	}
	
	&.type-c {
		>.data-list {
			>.data-item {
				>.data-wrap {
					flex-direction: column;
				}
			}
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-d
**/
.data-display.module-d {
	overflow: hidden;

	>.data-list {
		display: flex;
		flex-wrap: wrap;
		column-gap: 12rem;
		position: relative;
		left: -12rem;

		>.data-item {
			position: relative;
			padding-left: 12rem;

			&::before {
				content: '';
				display: block;
				position: absolute;
				top: calc((20rem * 0.5) - 12rem / 2);
				left: 0;
				width: 1rem;
				height: 12rem;
				background-color: color(normal, 040);
			}

			>.data-wrap {
				display: flex;
				column-gap: 8rem;
				@include font((outline: small-3x, size: 1.4)...);
				color: color(normal, 010);

				>.data-head {
					flex-shrink: 0;
					display: block;
	
					.data-name {
						display: block;
					}
				}
	
				>.data-body {
					display: block;
				}
			}
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-e
**/
.data-display.module-e {
	>.data-list {
		display: flex;
		flex-direction: column;
		row-gap: 16rem;

		>.data-item {
			>.data-wrap {
				display: flex;
				align-items: center;
				gap: 16rem;
				position: relative;

				>.data-head {
					>.data-subject {
						margin: 0;
						@include font((outline: small-3x, size: 1.4, weight: bold)...);
						color: color(normal, 010);
						
						>.data-name {
							display: flex;
							align-items: center;
							column-gap: 8rem;

							.data-counter {
								display: flex;
								align-items: center;
								justify-content: center;
							}
						}
					}					
				}
				>.data-body {
					position: relative;
					flex: 1 1 100%;					
					box-sizing: border-box;					

					.para {
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 020);
					}

					.data-list {
						display: flex;
						column-gap: 4rem;
						row-gap: 8rem;
						flex-wrap: wrap;

						.data-item {
							display: flex;
							column-gap: 16rem;
							position: relative;
							
							.head {
								@include font((outline: small-3x, size: 1.4, weight: medium)...);
								color: color(normal, 010);
							}

							.body {
								@include font((outline: small-3x, size: 1.4)...);
								color: color(normal, 010);
							}
						}
					}
				}
				.data-side {
					.data-list {
							display: flex;
							column-gap: 4rem;

							.data-item {
								.head {
									@include hidden();
								}
								.body {
									@include font((outline: small-3x, size: 1.4)...);
									color: color(normal, 030);
								}
							}
						}
				}			
			}
		}
	}

	&.style-b {
		>.data-list {
			>.data-item {
				padding: 20rem;				
				background-color: color(base, 005);
				border: 1rem solid color(normal, 040);			
				border-radius: 8rem;
				box-sizing: border-box;

				>.data-wrap {
					.data-head {
						.data-subject {
							.data-name {
								.data-counter {
									flex-shrink: 0;
									width: 20rem;
									height: 20rem;
									@include font((outline: small-4x, size: 1.3, weight: bold)...);
									color: color(base, 000);
									border-radius: 50%;
									background-color: color(accent, 010);
								}
							}
						}
					}
					.data-body {
						padding-right: 40rem;

						.data-list {
							.data-item {
								&.direct-column {
									flex: 1 1 100%;
								}

								&:not(:last-child, .direct-column) {
									margin-right: 12rem;
									padding-right: 12rem;
									box-sizing: border-box;

									::before {
										content: '';
										display: block;
										position: absolute;
										top: calc((20rem / 2) - 12rem/2);
										right: 0;
										width: 1rem;
										height: 12rem;
										background-color: color(normal, 040);
									}
								}

								&:not(.direct-column) {
									max-width: 30%;
								}

								.head {
									flex-shrink: 0;
									min-width: 56rem;
								}
							}
						}
					}
					.data-side {}	
				}
			}
		}
	}

	&.type-a {
		>.data-list {
			>.data-item {
				>.data-wrap {
					.data-head {
						.data-subject {
							width: 140rem;
							.data-name {}
						}
						.data-number {
						}
					}
				}
			}
		}
	}

	&.type-c {
		>.data-list {
			>.data-item {
				>.data-wrap {
					flex-direction: column;
					align-items: stretch;
					.data-head {
						.data-subject {
							padding-right: 145rem;

							.data-name {}
						}
						.data-number {
						}
					}
					.data-body {
						padding-left: 28rem;
					}
					.data-side {
						display: flex;
						position: absolute;
						top: 0;
						right: 0;
					
					}	
				}
			}
		}
	}

	&.attr-draggable {
		display: flex;
		flex-wrap: wrap;
		row-gap: 16rem;

		>.data-list {
			// flex: 1 1 100%;
			order: 2;
			width: 100%;

			>.data-item {
				user-select: none;
				cursor: grab;

				>.data-wrap {
					>.data-body {
						&::after {
							content: '';
							display: block;
							position: absolute;
							top: calc(50% - 24rem/2);
							right: 0;
							width: 24rem;
							height: 24rem;
							mask-repeat: no-repeat;
							mask-position: center;
							mask-size: cover;
							mask-image: icon(menu, color(normal, 010));
							background-color: color(normal, 010);
						}
					}
				}

				&.sortable-chosen {
					background-color: color(primary, 005);
					border: 1rem solid color(accent, 010);
					cursor: grabbing;
				}
				
				&.sortable-ghost {
					background-color: color(base, 005);
					border: 1rem solid color(base, 020);
	
					>.data-wrap {
						>.data-head {							
							>.data-subject {								
								>.data-name {
									color: color(normal, 040);

									>.data-counter {
										background-color: color(normal, 040);
										color: color(normal, 000);
									}
								}
							}
						}
						>.data-body {
							.para {
								color: color(normal, 040);
							}
						}
					}
				}
	
				&.sortable-drag {
					background-color: color(primary, 005);
					border: 1rem solid color(accent, 010);
					box-shadow: 0rem 6rem 20rem rgba(0, 0, 0, 0.14);
					opacity: 1 !important;				
				}
			}
		}

		>.data-util {
			flex: 1 1 100%;
			order: 1;
		}
	}
}

/**
 * @name		data-display
 * @moudle		module-f
**/
.data-display.module-f {
	display: flex;
	align-items: flex-start;
	column-gap: 16rem;

	>.data-list {
		flex: 1 1 100%;
		display: flex;
		flex-wrap: wrap;
		column-gap: 16rem;
		row-gap: 16rem;

		>.data-item {
			flex: 1 1 100%;
			position: relative;
			background-color: color(base, 005);
			
			border-radius: 8rem;
			box-sizing: border-box;

			&:not(.active) {
				.data-side {
					max-height: 0;
				}
			}

			&.active {				
				>.data-wrap {
					>.data-side {
						max-height: 100vh;

						&::before {
							content: '';
							display: block;
							position: absolute;
							z-index: 0;
							top: 0;
							left: 0;
							right: 0;
							bottom: 0;
						}
						
					}
				}
			}

			&.direct-column {
				max-width: calc(50% - 16rem/2);
			}

			&.col-1 {
				flex: 1;
				min-width: calc(25% - 12rem);
			}

			&.col-2 {
				max-width: calc(50% - 16rem/2);
			}

			>.data-wrap {
				overflow: hidden;
				display: flex;
				align-items: center;
				justify-content: space-between;
				position: relative;
				z-index: 1;
				min-height: 64rem;
				padding: 0 32rem;
				background-color: color(normal, 000);				
				border: 1rem solid color(normal, 040);
				border-radius: 8rem;
				box-sizing: border-box;

				>.data-head {
					display: flex;
					align-items: center;
					column-gap: 4rem;
					position: relative;
					
					>.data-subject {
						margin: 0;

						.data-name {
							@include font((outline: small-3x, size: 1.4)...);
							color: color(normal, 010);
						}
					}
					.btn {
						&.active {
							&::before {
								mask-image: icon(chevron-up, color(base, 100));
							}
						}

						&::before {
							content: '';
							display: block;
							position: relative;
							width: 20rem;
							height: 20rem;
							background-color: color(normal, 010);
							mask-image: icon(chevron-down, color(base, 100));
							mask-repeat: no-repeat;
							mask-position: center;
							mask-size: cover;
						}

						.btn-text {
							@include hidden;
						}
					}
				}
				>.data-body {
					max-width: 70%;
					@include font((outline: small-2x, size: 1.5, weight: medium)...);
					color: color(normal, 010);
					word-break: break-word;	
				}
			}

			>.data-side {
				overflow: hidden;
				flex: 1 1 100%;
				transition: opacity .3s ease-in-out;

				&::before {
					content: '';
					display: block;
					position: absolute;
					top: 0;
					left: 0;
					right:0;
					bottom: 0;
					z-index: 0;
					border: 1rem solid color(normal, 040);
					border-radius: 8rem;
					box-sizing: border-box;
				}
				
				>.data-list {
					>.data-item {
						display: flex;
						flex-wrap: wrap;
						align-items: center;
						justify-content: space-between;
						min-height: 60rem;
						padding: 0 40rem;

						+.data-item {
							border-top: 1rem solid color(normal, 040);
						}

						.head {
							display: flex;
							column-gap: 4rem;
							@include font((outline: small-3x, size: 1.4)...);
							color: color(normal, 010);
						}
						.body {
							@include font((outline: small-2x, size: 1.5, weight: medium)...);
							color: color(normal, 010);
						}

						&:not([class*="attr-"]) {
							.head {
								padding-left: 24rem;
							}
						}

						&[class*="attr-"] {
							.head {
								&::before {
									content: '';
									flex-shrink: 0;
									display: block;
									width: 20rem;
									height: 20rem;
									margin: 0 auto;
									background-repeat: no-repeat;
									background-position: center;
									background-size: auto 100%;
									background-color: color(normal, 010);
									mask-repeat: no-repeat;
									mask-size: auto 100%;
									mask-position: center
								}
							}
						}

						&.attr-arrow-bent {
							.head {
								&::before {
									mask-image: icon(arrow-bent, color(normal, 010));
								}
							}
						}
					}
				}

				>.data-display.landing-page-url {
					>.data-list {
						row-gap: 0;
						>.data-item {
							+.data-item {
								border-top: 1rem solid color(normal, 040);
							}
						}
					}
				}
			}
		}
	}
}

