//data-display process-step
.data-display.process-step {
	.order-list {
		display: flex;
		justify-content: center;
		column-gap: 94rem;
		counter-reset: order-count;

		.order-item {
			display: flex;
			align-items: baseline;
			// column-gap: 20rem;
			position: relative;
			counter-increment: order-count;

			&.current {
				.order-wrap {
					.order-head {
						.order-subject {
							color: color(accent, 010);
						}

						&::before {
							content: '';
							background-image: icon(check, color(accent, 000));
							background-repeat: no-repeat;
							background-position: center;
							background-size: auto 28rem;
							background-color: color(accent, 010);
							border-color: color(accent, 010);
						}
					}
				}
			}

			&:not(:last-child) {
				&::after {
					content: '';
					display: block;
					position: absolute;
					top: 20rem;
					left: calc(100% + 41rem/2);
					width: 54rem;
					height: 11rem;
					background: url(./../images/svg/dots.svg) no-repeat center;
					background-size: auto 11rem;
				}
			}

			.order-wrap {
				display: flex;
				align-items: center;
				justify-content: center;

				.order-head {
					display: flex;
					flex-direction: column;
					align-items: center;
					row-gap: 8rem;
					position: relative;

					&::before {
						content: counter(order-count);
						display: flex;
						align-items: center;
						justify-content: center;
						width: 48rem;
						height: 48rem;
						background-color: color(normal, 000);
						border: 4rem solid color(base, 020);
						border-radius: 100%;
						box-sizing: border-box;
						@include font((outline: small-1x, size: 1.4)...);
						color: color(normal, 030);
					}
					
					.order-subject {
						display: flex;
						margin: 0;
						@include font((outline: small-1x, size: 1.4, weight: medium)...);
						color: color(normal, 030);

						.order-name {
						}
					}
				}
			}
		}
	}
}

