@import '_variables';

.em svg {
	display: block;
	position: relative;
	top: 0;
	left: 0;
}

em.em {
	font-style: normal;
}

a.em {
	&:not([class*=normal-]):not([class*=accent-]) {
		color: inherit;
	}
}

mark.em {
	background-color: transparent;
}

a.em,
strong.em,
span.em {
	display: inline-flex;
}

.para {
	margin: 0;
}

.para,
.em {
	&.type-a {
	}

	&.type-b {
		text-align: right;
	}
	&.type-c {
		text-align: center;
	}

	// accent
	@each $name, $font-color in $text-accent {
		&.#{$name} {
			color: $font-color;
		}
	}
}