/**
 * @name		data-table
 * @moudle		module-c
**/
 .data-table.module-c {
	 &.attr-scroll {
		width: 100%;
		@include overflow-scroll(default, dark, large, x);
		box-sizing: border-box;

		>table {
			min-width: 1400rem;
		}
	}
	
	border-bottom: 1rem solid color(base, 020);
	
	>table {
		table-layout: fixed;
		width: 100%;
		border-spacing: 0;
		border-collapse: collapse;
		border-right: hidden;
		border-left: hidden;
		
		caption {
			// overflow: hidden;
			// margin: -1px;
			// padding: 0;
			// width: 1px;
			// height: 1px;
			// line-height: 1px;
			// font-size: 1px;
			// color: transparent;
			// border: 0;
			// clip: rect(0 0 0 0);
			// clip: rect(0,0,0,0);
			
			@include hidden(caption);
		}

		>thead {
			>tr {
				>th {
					.data-wrap {
						display: flex;
						justify-content: center;
						align-items: center;
						position: relative;

						.tooltip.module-b {
							position: absolute;
							z-index: 1;
							left: 50%;
							top: calc(100% + 8rem);
							transform: translateX(-50%);
						}
					}

					padding: 20rem 0;
					border-bottom: 1rem solid color(accent, 010);
					background-color: color(primary, 005);
					color: color(accent, 060);
					@include font((outline: small-2x, size: 1.5, weight: medium)...);			
					
					// 변경될 수 있음
					&.hidden {
						overflow: hidden;
						text-indent: -9999px;
					}
					
					.form.checkbox {
						vertical-align: middle;
					}
					
					.em.attr-setting {
						display: flex;
						column-gap: 4rem;
						justify-content: center;
						align-items: center;
						color: inherit;
						text-decoration: none;

						&::after {
							content: '';
							display: block;
							width: 24rem;
							height: 24rem;
							mask-repeat: no-repeat;
							mask-position: center;
							mask-size: cover;
							mask-image: icon(setting-fill, color(normal, 030));
							background-color: color(primary, 030);
						}

						&:not(:hover) ~.tooltip {
							display: none;
						}
					}
				}
			}
		}

		>tbody {
			>tr {
				>th {
					padding: 20rem;
					@include font((outline: small-2x, size: 1.5)...);
					color: color(normal, 010);
					vertical-align: middle;

					>.wbr {
						display: block;
					}

					+td{
						border-left: 0;
					}		
					
				}

				>td {
					height: 56rem;
					padding: 8rem;
					box-sizing: border-box;
					@include font((outline: small-3x, size: 1.4)...);
					vertical-align: middle;
					color: color(normal, 010);
					white-space: normal;

						&[class*="attr-"] {
							&::before {
								content: '';
								display: inline-block;
								width: 20rem;
								height: 20rem;
								margin: 0 4rem 0 auto;
								background-color: color(normal, 010);
								background-repeat: no-repeat;
								background-position: center;
								background-size: auto 100%;
								vertical-align: middle;
								mask-repeat: no-repeat;
								mask-position: center;
								mask-size: cover;
							}		
					}
					.wbr {
						display: inline-block;
					}

					.em {
						@include font((outline: small-3x, size: 1.4, weight: medium)...);
						text-overflow: ellipsis;
						
						&.accent-01 {
							@include font((weight: bold)...);
						}
					}

					span.em {
						&.accent-01 {
							@include font((weight: medium)...);
						}
					}

					.form.checkbox  {
						vertical-align: middle;
					}

					&.campaign-name {
						// display: inline-block;
						overflow: hidden;
						@include font((outline: small-3x, size: 1.4, weight: medium)...);
						// color: inherit;
						text-overflow: ellipsis;
						text-align: left;
						white-space: nowrap;

						a {
							color: inherit;

							&:not(:hover) {
								text-decoration: none;
								color: inherit;
							}
						}
					}

					>img {
						vertical-align: middle;
					}

					>svg {
							vertical-align: middle;
							fill: color(normal, 010);
						}

					>.button-area {
						.btn {
							min-width: 64rem;
						}
					}

					.data-more {
						position: relative;

						.btn {
							display: inline-flex;
							border-radius: 4rem;

							&::before {
								content: '';
								display: block;
								position: relative;
								z-index: 1;
								width: 32rem;
								height: 32rem;
								mask-repeat: no-repeat;
								mask-position: center;
								mask-size: 28rem auto;
								mask-image: icon(more, color(base, 060));
								background-color: color(normal, 030);
							}

							&:hover {
								background-color: rgba(0,0,0,.04);
							}

							&:focus-within {
								background-color: rgba(0,0,0,.08);
							}

							.btn-text {
								@include hidden;
							}
						}


						&:not(.active) {
							.tooltip.module-c {
								display: none;
							}
						}
					}

					.mark.module-a {
						display: inline-flex;
						min-width: 72rem;
						
						~.button-area {
							margin-left: 4rem;
						}
					}

					.option-list {
						.option-item {
							.form {
								vertical-align: middle;
							}
						}
					}

					.data-display {
						display: flex;
						column-gap: 4rem;
						align-items: center;
						justify-content: center;
						
						.data-list {
							.data-item {
								.data-wrap {}
							}
						}
						.button-display {
							.button-area {
								display: flex;
								column-gap: 8rem;

								svg {
									fill: color(normal, 030);
								}
							}
						}						
					}
					
					.info-board {
						padding: 136rem 0;
					}
				}

				&+tr { 
					>th {
						border-top: 1rem solid color(base, 020);
					}
					>td {
						border-top: 1rem solid color(base, 020);
					}
				}
			}
		}
	}

	&.style-b {
		>table{
			>thead {
				>tr {
					>th {
					}
				}
			}
			>tbody {
				>tr {
					&:hover {
						>td {
							background-color: color(normal, 050);
						}
					}
					>th {}
					>td{}
				}
			}
		}
	}

	&.style-c {
		>table{
			>thead {
				>tr {
					>th {
						padding: 16rem;
						border-right: 0;
						border-left: 0;
					}
				}
			}
			>tbody {
				>tr {
					>th {
						padding: 12rem;
						border-right: 0;
						border-left: 0;
					}

					>td{
						padding: 12rem;
						border-right: 0;
						border-left: 0;
						color: color(normal, 030);
						@include font((outline: small-3x, size: 1.4)...);
					}
				}
			}
		}
	}

	&.type-c {
		text-align: center;
		vertical-align: middle;
	}

	&+.em {
		margin-top: 16rem;
	}



	&.attr-menu-list {
		tbody {
			tr {
				td {
					.data-name {
						overflow: hidden;
						display: block;
						@include font((outline: small-3x, size: 1.4)...);
						color: inherit;
						text-overflow: ellipsis;
						white-space: nowrap;
						text-align: left;

						&:not(:hover) {
							text-decoration: none;
							color: inherit;
						}
					}
	
					.data-path {
						text-align: left;
					}

					.data-code {
						
					}
				}

				&.depth-01 {
					td {
						.data-name {
							@include font((weight: medium)...);
						}
					}
				}

				&.depth-02 {
					td {
						background-color: color(base, 005);

						.data-name {
							display: flex;
							column-gap: 4rem;
							align-items: center;

							&:before {
								content: '';
								display: block;
								width: 20rem;
								height: 20rem;
								mask: icon(arrow-bent, color(base, 100)) no-repeat center/cover;
								background-color: color(normal, 010);
							}
						}
					}
				}
			}
		}
	}
}

