//  [의미 및 기능]
//  * 절대적으로 있어야 하는 구성요소
 
//  1. legend 반드시 포함
//  2. 항목이 분류 되어야 함
//  3. 항목은 label 존재 해야함
//  3. form은 단독적인 기능을 폼함할 수 있음 (form 항목과 버튼이 동일하게 존재할 수 있음)
//  4. form 가이드 영역
//  5. valid, invalid 영역
//  6. 전송 버튼
 
//  [시각적 분류]
 
//  1. legend 비노출 여부
//  2. label 비노출 여부
//  3. label 배치 (세로, 가로)


@mixin direct-column {
	&:not(.direct-column) {
		flex-direction: column;
	
		>.form-list {
			flex-direction: column;
		}	
	}
}

@mixin direct-row {
	&.direct-row {
		flex-direction: row;
		flex-wrap: wrap;
	
		>.form-list {
			flex-direction: row;
			flex-wrap: wrap;
		}	
	}
}

/**
 * @name submit-form
**/
.submit-form {
	display: flex;
	margin: 0;
	padding: 0;
	border: hidden;

	>legend {
		@include hidden;
	}

	>.form-list {
		display: flex;
		flex: 1 1 100%;

		>.form-item {
			&.flex {
				flex: 1 1 100%;
			}

			@include most-outer-selector(":not(.direct-column)") {
				flex: 1 1 100%;
			}

			>.form-wrap {
				display: flex;

				// type
				@include most-outer-selector(".type-a") {
					flex-direction: row;
					column-gap: 16rem;

					>.form-head {
						flex-shrink: 0;
					}

					>.form-body {
						flex: 1 1 100%;
					}
				}

				@include most-outer-selector(".type-c") {
					flex-direction: column;
					row-gap: 8rem;
				}

				>.form-head {
					// type
					@include most-outer-selector(":not([class*=type-])") {
						@include hidden;
					}

					@include most-outer-selector("[class*=type-]") {
						display: flex;
						align-items: center;

						.form-subject {
							margin: 0;
							display: flex;
							align-items: center;
	
							.form-name {
								display: block;
	
								// module
								@include most-outer-selector(".module-a") {
									@include font((weight: regular)...);
								}
	
								@include most-outer-selector(".module-b") {
									@include font((weight: medium)...);
								}
	
								@include most-outer-selector(".module-c") {
									@include font((weight: bold)...);
								}
							}
		
							// outline
							@include most-outer-selector(".large-4x") {
								column-gap: 8rem;
	
								.form-name {
									@include font((outline: small-2x, size: 1.5)...);
								}
							}
	
							@include most-outer-selector(".large-6x") {
								column-gap: 12rem;
	
								.form-name {
									@include font((outline: small-2x, size: 1.3)...);
								}
							}
						}
					}
				}

				>.form-body {
					flex: 1 1 00%;

					>.form-area {
						display: flex;
						align-items: center;
						column-gap: 8rem;

						>.flex {
							flex: 1 1 100%;
						}

						>:not(.flex) {
							flex-shrink: 0;
						}

						.sign {
							display: flex;
							min-width: 1em;
							justify-content: center;
							align-items: center;
							text-align: center;
						}
					}

					.form-noti {
						flex: 1 1 100%;
						margin: 8rem 0 0;
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 030);

						&.valid {
							color: color(accent, 050);
						}

						&.invalid {
							color: color(accent, 040);
						}
					}

					.form-para {
						margin: 0;
					}
				}

				>.form-side {
					flex: 1 1 100%;
					
					.submit-form.module-b {
						width: 100%;
						margin: 12rem 0 0;
					}
				}

				.tooltip.module-d {
					.tooltip-wrap {
						.tooltip-body {
							.submit-form {
								flex-direction: column;
							}
							
							.form-area {
								align-items: flex-end;

								.sign {
									margin-bottom: 44rem;
								}
							}
						}
					}
				}
			}
		}
	}

	&.large-4x {
		@include most-outer-selector(".direct-column") {
			column-gap: 16rem;
		}

		>.form-list {
			@include most-outer-selector(".direct-column") {
				column-gap: 16rem;
			}

			>.form-item {
				>.form-wrap {
					@include most-outer-selector(".module-c") {
						row-gap: 12rem;
					}

					>.form-head {
						@include most-outer-selector(".type-a") {
							height: 48rem;

							@include most-outer-selector(":not(.direct-column)") {
								width: 104rem;
							}
						}
					}
				}
			}
		}

		&.style-a {
			>.form-list {
				@include most-outer-selector(":not(.direct-column)") {
					row-gap: 24rem;
				}
			}
		}

		&.style-b {
			>.form-list {
				>.form-item {
					+.form-item {
						padding-top: 32rem;
						border-top: 1rem solid color(normal, 050);
					}
				}
			}
		}

		&.type-c {
			>.form-list {
				@include most-outer-selector(":not(.direct-column)") {
					row-gap: 32rem;
				}

				@include most-outer-selector(".direct-row") {
					column-gap: 16rem;

					>.form-item {
						&.col-2 {
							flex: 1 0 calc(50% - 8rem);
						}
					}
				}
			}
		}
	}

	&.large-6x {
		@include most-outer-selector(".direct-column") {
			column-gap: 16rem;
		}

		>.form-list {
			@include most-outer-selector(".direct-column") {
				column-gap: 16rem;
			}

			>.form-item {
				>.form-wrap {
					>.form-head {
						@include most-outer-selector(".type-a") {
							height: 56rem;

							@include most-outer-selector(":not(.direct-column)") {
								width: 104rem;
							}
						}
					}
				}
			}
		}

		&.style-a {
			@include most-outer-selector(".type-c") {
				row-gap: 48rem;
			}

			@include most-outer-selector(":not(.direct-column)") {
				>.form-list {
					row-gap: 36rem;
				}
	
				>.form-util {
					.button-display {
						display: flex;
			
						.button-area {
							flex: 1 1 100%;
							display: flex;
							column-gap: 8rem;
			
							.flex {
								flex: 1 1 100%;
							}
						}
					}
				}
			}
		}

		&.style-d {
			@include most-outer-selector(":not(.direct-column)") {
				row-gap: 32rem;

				>.form-list {
					row-gap: 8rem;
				}

				>.form-util {
					.button-display {
						display: flex;
						flex-direction: column;
						row-gap: 8rem;
			
						.button-area {
							display: flex;

							.flex {
								flex: 1 1 100%;
							}
						}
					}
				}
			}
		}
	}

	&.direct-column {
		>.form-util {
			.button-display {
				display: flex;
	
				.button-area {
					flex: 1 1 100%;
					display: flex;
					column-gap: 8rem;
	
					.flex {
						flex: 1 1 100%;
					}
				}
			}
		}
	}
}

/**
 * @name		submit-form
 * @moudle		module-b
**/
.submit-form.module-b {
	@include direct-column;
	@include direct-row;

	>.form-list {
		>.form-item:not(.checked-within) {
			>.form-wrap {
				>.form-side {
					display: none;
				}
			}
		}

		>.form-item {
			>.form-wrap {
				>.form-body {
					.submit-form.module-b.style-d {
						>.form-list {
							row-gap: 8rem;
	
							>.form-item {				
								padding: 20rem;
								background-color: color(base, 005);
								
								>.form-wrap {
									.form-body {
										display: flex;
										flex-direction: column;
										row-gap: 8rem;
									}
								}
							}
						}
					}
				}
				>.form-side {
					.submit-form.module-b {
						>.form-list {
							row-gap: 8rem;
	
							>.form-item {				
								padding: 20rem;
								background-color: color(base, 005);
								
								>.form-wrap {
									.form-body {
										display: flex;
										flex-direction: column;
										row-gap: 8rem;
									}
								}
							}
						}
					}

					.form-para {
						+.option-list {
							margin-top: 0;
						}
					}
				}
			}
		}
	}
	
	.option-list.module-a {
		margin: 12rem 0;
	}

	.col-2 {
		flex-shrink: 0;
		width: calc(50% - 16rem / 2);
	}
}

/**
 * @name		submit-form
 * @moudle		module-c
**/
.submit-form.module-c {
	@include direct-column;

	>.form-list {
		>.form-item {
			>.form-wrap {
				>.form-body {
					.form-area {
						&:not(:first-child) {
							margin-top: 24rem;
						}
					}

					.form-para {
						margin-top: 12rem;
						color: color(normal, 030);
					}

					>.option-list {
						.option-item {
							column-gap: 8rem;
							
							.form {
								align-items: center;
							}
						}
					}
				}
			}
		}
	}

	&.style-b {
		>.form-list {
			>.form-item:not(.checked-within) {
				>.form-wrap {
					>.form-body {
						display: none;
					}
				}
			}
		}
	}
}

/**
 * @name		submit-form
 * @moudle		module-d
**/
.submit-form.module-d {
	margin: 0;
	padding: 0;
	border: hidden;
	display: flex;
	flex-direction: column;
	row-gap: 48rem;

	>legend {
		@include hidden;
	}

	>.form-list {
		display: flex;
		flex: 1 1 100%;
		flex-direction: column;
		row-gap: 36rem;

		>.form-item {
			>.form-wrap {
				display: flex;

				>.form-head {
					.form-name {
						@include font((outline: small-2x, size: 1.3, weight: medium)...);
					}
				}

				>.form-body {
					display: flex;
					flex-direction: column;
					flex: 1 1 100%;
					row-gap: 4rem;

					>.form-area {
						display: flex;
						// flex-wrap: wrap;
						column-gap: 16rem;
						align-items: center;

						>.form {
							&.flex {
								flex: 1 1 100%;
							}
							&:not(.flex) {
								flex-shrink: 0;
							}

							>.form-elem {}
						}

						.button-area {
							display: flex;
							column-gap: 8rem;
						}
					}
				}
			}
		}
	}

	&:not([class*=type-]) {
		>.form-list {
			>.form-item {
				>.form-wrap {
					>.form-head {
						@include hidden;
					}
				}
			}
		}
	}

	&.style-b {
		row-gap: 32rem;
		
		>.form-list {
			row-gap: 8rem;

			.form-item {
				>.form-wrap {
					>.form-head {
						@include hidden();
					}
				}
			}
		}
	}

	&.type-a {
		>.form-list {
			.form-item {
				>.form-wrap {
					column-gap: 32rem;
					align-items: baseline;

					>.form-head {
						min-width: 88rem;
					}
				}
			}
		}
	}

	&.type-b {
		>.form-list {
			.form-item {
				>.form-wrap {
					>.form-head {
					}
				}
			}
		}
	}
	
	&.type-c {
		>.form-list {
			.form-item {
				>.form-wrap {
					flex-direction: column;
					row-gap: 12rem;

					>.form-head {
						.form-subject {
							margin: 0;
						}
					}
					>.form-body {
						>.form-area {
							>.form {
								>.form-elem {}
							}
						}
					}
				}
			}
		}
	}

	&.type-d {
		>.form-list {
			.form-item {
				>.form-wrap {
					>.form-head {
					}
				}
			}
		}
	}

	>.button-display.module-a {
		position: relative;

		>.button-area {
			display: flex;
			position: relative;
		}
	}

}

/**
 * @name		option-list
 * @moudle		module-a
**/
.option-list.module-a {
	display: flex;
	flex-wrap: wrap;
	row-gap: 16rem;
	column-gap: 24rem;	
	padding: 0;

	.option-item {
		display: inline-flex;
		flex-wrap: wrap;
		position: relative;

		&:not(:hover) {
			.option-wrap {
				.option-body {
					.tooltip.module-b {
						visibility: hidden;
						opacity: 0;
					}
				}
			}
		}

		>&:not(.checked-within) {
			>.form {
				+div.submit-form {
					display: none;
				}
			}
		}

		>.form {
			+div.submit-form {
				flex: 1 1 100%;
				width: 100%;
				margin: 12rem 0 0;
			}
		}

		.option-wrap {
			display: flex;
			flex-direction: column;
			// row-gap: 12rem;

			.option-head {
				.option-subject {
					display: flex;
					margin: 0;

					.option-name {
						display: inline-flex;
						@include font((outline: small-2x, size: 1.5)...);
					}
				}
			}
			.option-body {
				// display: none;

				.form.textfield {
					display: flex;
					max-width: 800rem;
				}
			}
		}

	}

	&.style-b {
		flex-direction: column;
		column-gap: 12rem;
		
		.option-item {
			flex: 1 1 100%;
			display: flex;
			// flex-direction: column;
			// align-items: flex-start;
		
			&:not(.checked-within) {
				.option-wrap {
					.option-head {}
					.option-body {
						display: none;								
						margin-top: 0;
					}
				}
			}
			.option-wrap {
				flex: 1 1 100%;

				.option-body {						
					margin-top: 12rem; 
				}
			}
		}
	}
	.type-a {}
	.type-b {}
	.type-c {}
}

/**
 * @name		option-list
 * @moudle		module-b
**/
.option-list.module-b {
	display: flex;
	flex-wrap: wrap;
	row-gap: 8rem;
	column-gap: 8rem;
	margin: 0;
	padding: 0;

	.option-item {
		display: inline-flex;
		position: relative;

		.tooltip.module-b {
			position: absolute;
			z-index: 1;
			top: calc(100% + 12rem);
			left: 50%;
			transform: translateX(-50%);


			visibility: hidden;
			opacity: 0;
			transition: visibility 0.25s ease, opacity 0.25s ease;
		}


		&:focus-within, 
		&:hover {
			.tooltip.module-b {
				visibility: visible;
				opacity: 1;
			}
		}


		
	}

	&.style-b {
		flex-direction: column;

		.option-item {
			display: flex;
			flex: 1 1 100%;
		}
	}
	.type-a {}
	.type-b {}
	.type-c {}
}

/**
 * @name		file-upload
 * @moudle		module-a
**/
.file-upload.module-a {
	display: flex;

	.upload-wrap {
		flex: 1 1 100%;

		.upload-head {
			.file-to-upload {
				display: flex;
				column-gap: 12rem;

				.form {
					flex: 1 1 100%;
				}

				.btn {
					flex-shrink: 0;
					
				}
			}
			.file-noti {
				flex: 1 1 100%;
				margin: 4rem 0 0;
				@include font((outline: small-3x, size: 1.4)...);
				color: color(normal, 030);
			}
		}
	}
}

/**
 * @name		option-display
 * @moudle		module-b
**/
.option-display.module-b {
	margin: 0;
	padding: 0;
	border: hidden;

	legend {
		@include hidden;
	}

	.option-list {
		display: flex;
		flex-wrap: wrap;
		row-gap: 12rem;
		column-gap: 12rem;

		.option-item {
			flex: 1 1 100%;
			position: relative;
			background-color: color(base, 005);
			border: 1rem solid color(normal, 040);
			border-radius: 4rem;
			box-sizing: border-box;

			&.checked-within {
				border: 1rem solid color(accent, 010);
				background-color: color(primary, 005);

				.option-wrap {
					.option-head {
						.option-subject {
							.option-name {
								color: color(accent, 060);
								.form {
									.form-text {
										&::before {
											background-color: color(accent, 060);
										}
									}
								}
							}
						}
						.option-summary {
							color: color(accent, 010);
						}
					}

					&::after {
						filter: grayscale(0);
						opacity: 1;
					}
				}
			}
			
			.option-wrap {
				display: flex;
				justify-content: space-between;
				align-items: center;
				column-gap: 16rem;
				// position: relative;
				padding: 32rem 24rem;

				&::after {
					content: '';
					display: block;
					flex-shrink: 0;
					width: 120rem;
					height: 120rem;
					filter: grayscale(1);
					opacity: .8;
					pointer-events: none;
				}

				.option-head {
					display: flex;
					flex-direction: column;
					row-gap: 12rem;
					
					.option-subject {
						margin: 0;

						.option-name {
							display: block;
							@include font((outline: small-2x, size: 1.5, weight: medium)...);
							color: color(normal, 020);

							.form {
								display: block;

								.form-elem {
									position: absolute;
									z-index: 0;
									top: 0;
									left: 0;
									right: 0;
									bottom: 0;
									cursor: pointer;

									margin: 0;
									padding: 0;
									box-sizing: border-box; // textarea 적용안됨
									appearance: none;
								}

								.form-text {
									display: flex;
									column-gap: 8rem;
									
									&::before {
										content: '';
										display: block;
										width: 24rem;
										height: 24rem;
										background-color: color(normal, 020);
										mask-repeat: no-repeat;
										mask-position: center;
										mask-size: cover;
										mask-image: icon(check, color(normal, 020));
									}
								}
							}
						}
					}

					.option-summary {
						margin: 0;
						@include font((outline: small-2x, size: 1.5)...);
						color: color(normal, 030);
					}
				}
			}

			&.vertical {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/vertical.svg);
					}
				}
			}
			&.horizontal {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/horizontal.svg);
					}
				}
			}
			&.img-floating {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/img-floating.svg);
					}
				}
			}
			&.text-floating {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/text-floating.svg);
					}
				}
			}
			&.mini-floating {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/mini-floating.svg);
					}
				}
			}
			&.banner {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/banner.svg);
					}
				}
			}
			&.multi-floating {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/multi-img-floating.svg);
					}
				}
			}
			&.action-floating {
				.option-wrap {
					&::after {
						background-image: url(../../assets/images/svg/action-floating.svg);
					}
				}
			}
		}
	}
}

// form-list time
.form-list.time {
	.form-item {
		.form-wrap {
			flex-direction: column;
			
			.form-head {
				@include hidden;
			}
			.form-body {
				.option-list {
					flex: 1 1 100%;
					display: flex;
					justify-content: space-between;
					flex-wrap: wrap;
					gap: 6rem;
					
					.option-item {
						width: calc(12.5% - 6rem);
					}
				}
				.form {
