
/**
 * @name		goods-display
 * @moudle		module-b
**/
.goods-display.module-b {
	display: flex;
	flex-direction: column;

	.goods-list {
		order: 2;
		display: flex;
		flex-wrap: wrap;

		.goods-item {
			position: relative;

			&.checked {
				.goods-wrap {
					.goods-select {
						.form {
							.form-elem {}
							.form-text {}
						}
					}
					.goods-inform {
						.goods-head {
							.goods-subject {}
						}
						.goods-body {} 
					}
				}
			}

			.goods-wrap {
				.goods-select {
					.form {
						.form-text {
							@include hidden;
						}
					}
				}
				.goods-inform {
					.goods-head {
						overflow: hidden;

						.goods-subject {
							margin: 0;
							@include font((outline: small-2x, size: 1.5, weight: bold)...);
						}
					}
					.goods-body {} 
				}
			}
		}	
	}

	.goods-util {
		order: 1;
		
		.button-display {
			display: flex;

			.button-area {
				display: flex;

				.btn {
					display: flex;
					align-items: center;
					justify-content: center;
					width: 32rem;
					height: 32rem;
					border-radius: 4rem;

					&::before {
						content: '';
						display: block;
						width: 28rem;
						height: 28rem;
						mask-repeat: no-repeat;
						mask-position: center;
						mask-size: cover;
						background-color: color(normal, 020);
					}

					&.disabled,
					&:disabled {
						&::before {
							background-color: color(normal, 040);
						}
					}


					&:not(.disabled):not(:disabled) {
						&:hover {
							background-color: rgba(0, 0, 0, 0.04);
						}

						&:focus-within {
							background-color: rgba(0, 0, 0, 0.08)
						}
					}

					.btn-text {
						@include hidden;
					}
				}

				.btn.delete {
					&::before {							
						mask-image: icon(delete, color(normal, 020));
					}
				}
			}

			&.type-b {
				justify-content: flex-end;
			}
		}
	}

	&.style-b {
		row-gap: 8rem;

		.goods-list {
			row-gap: 16rem;
			column-gap: 16rem;

			&.mini {
				.goods-item {
					.goods-wrap {
						.goods-inform {
							.goods-head {
								.goods-subject {
									@include ellipsis(2);
								}
							}
						}
					}
				}
			}
			
			&.banner {
				.goods-item {
					.goods-wrap {
						.goods-select .form {
							top: calc(50% - 24rem/2);
						}
						.goods-inform {
							.goods-head {
								display: flex;
								align-items: center;
								padding: 0 48rem 0 12rem;
		
								.goods-subject {
									@include ellipsis(1);
								}
							}
						}
					}
				}
			}

			.goods-item {
				overflow: hidden;
				border-radius: 4rem;

				&.checked-within {
					.goods-wrap {
						.goods-inform {
							.goods-head {
								background: rgba(0, 0, 0, 0.5);

								.goods-subject {
									color: color(normal, 000);
								}
							}
						}
					}
				}

				&:hover {
					.goods-wrap {
						.goods-inform {
							.goods-head {
								background: rgba(0, 0, 0, 0.5);

								.goods-subject {
									color: color(normal, 000);
								}
							} 
						}
					}
				}

				.goods-wrap {
					.goods-select {
						position: absolute;
						z-index: 2;
						top: 0;
						left: 0;
						right: 0;
						bottom: 0;

						.form {
							position: absolute;
							top: 12rem;
							right: 12rem;

							.form-text {
								@include hidden;
							}
						}
					}
					.goods-inform {
						.goods-head {
							position: absolute;
							top: 0;
							right: 0;
							left: 0;
							bottom: 0;
							padding: 12rem 48rem 12rem 12rem;
							transition: all .3s;

							.goods-subject {
								color: transparent;
							}
						}
						.goods-body {
							display: flex;
							flex-direction: column;
						}
					}
				}
			}
		}
	}
}