/**
 * @type module
 * @name info-board
 * @modle a
**/
.info-board.module-a {
	.board-wrap {
		display: flex;
		flex-direction: column;
		
		.board-head {
			display: flex;
			flex-direction: column;
			row-gap: 8rem;

			.board-subject {
				margin: 0;
				@include font((outline: large-3x, size: 1.35, weight: bold)...);
				color: color(normal, 010);
			}

			.board-summary {
				margin: 0;
				@include font((outline: small-2x, size: 1.5)...);
				color: color(normal, 020);

				strong {
					@include font((outline: small-2x, size: 1.5, weight: medium)...);
				}
			}
		}

		.board-util {
			margin-top: 24rem;
			
			.button-display {
				display: flex;

				.button-area {
					flex: 1 1 100%;
					display: flex;
					justify-content: center;
				}
			}
		}

		.wbr {
			display: block;
		}
	}

	&.style-b {
		padding: 20rem 0;
		background-color: color(primary, 005);
		text-align: center;

		.board-wrap {
			display: flex;
			justify-content: center;
			align-items: center;

			.board-head {
				.board-subject {}
				.board-summary {
					@include font((outline: small-3x, size: 1.4)...);
					color: color(accent, 010);
				}
			}
		}
	}

	&.type-b {
		.board-wrap {
			.board-head {
				align-items: flex-end;
			}
		}
	}

	&.type-c {
		.board-wrap {
			.board-head {
				align-items: center;
				text-align: center;
			}
			.board-body {
				display: flex;
				flex-direction: column;
				align-items: center;
				text-align: center;
			}
		}
	}

	&[class*="attr-"] {
		.board-wrap {
			&::before {
				content: '';
				flex-shrink: 0;
				display: block;
				width: 120rem;
				height: 120rem;
				margin: 0 auto;
				background-repeat: no-repeat;
				background-position: center;
				background-size: auto 100%;
			}
		}		
		.board-head {
			row-gap: 0;
			
			>.button-area {
				display: flex;
				margin-top: 24rem;
			}
		}
	}

	&.attr-nodata {
		.board-wrap {
			&::before {
				margin-bottom: 16rem;
				background-image: url(../../assets/images/svg/no-data.svg);
			}
		}		
	}
}

/**
 * @type module
 * @name info-board
 * @modle b
**/
.info-board.module-b {
	display: flex;
	flex-direction: column;

	.wbr {
		display: block;
	}

	.board-wrap {
		.board-head {
			@include most-outer-selector("[class*=attr-error-]") {
				&::before {
					content: attr(title);
					display: block;
					text-align: center;
					color: color(primary, 040);
					@include font((outline: small-1x, size: 1.3, weight: bold)...);
				}
			}

			.board-subject {				
				margin: 0;
				@include font((outline: large-2x, size: 1.4, weight: bold)...);
				color: color(accent, 060);

				@include most-outer-selector("[class*=attr-]") {
					margin-top: 56rem;
				}
			}

			.board-summary {
				margin: 16rem 0;
				@include font((outline: small-2x, size: 1.4)...);
				color: color(normal, 020);
			}

			~.board-body {
				margin: 16rem 0;
			}
		}

		.board-body {
			display: flex;
			flex-direction: column;

			.noti-board{
				.board-wrap {
					.board-head {
						.board-subject {
							@include font((outline: small-3x, size: 1.4, weight: regular)...);
							color: color(normal, 020);

							&::before {
								width: 20rem;
								height: 20rem;
								background-color: color(normal, 020);
							}
						}
					}
				}
			}
		}
		
		>.board-util {
			margin-top: 56rem;

			.button-display {
				display: flex;
				flex-direction: column;
				row-gap: 8rem;
				margin: 0 auto;
				width: 460rem;
				max-width: 100%;
	
				.button-area {
					flex: 1 1 100%;
					display: flex;
					column-gap: 8rem;
	
					.flex {
						flex: 1 1 100%;
					}
				}
			}
		}
	}

	&[class*="attr-"] {
		>.board-wrap {
			&::before {
				content: '';
				display: block;
				margin: 0 auto;
				width: 176rem;
				height: 176rem;
				background-repeat: no-repeat;
				background-position: 0 0;
				background-size: 100% auto;

				@include most-outer-selector(".attr-applied") {
					background-image: url(../../assets/images/svg/success.svg);
				}

				@include most-outer-selector(".attr-error-404") {
					background-image: url(../../assets/images/svg/question.svg);
				}
			
				@include most-outer-selector(".attr-error-500") {
					background-image: url(../../assets/images/svg/exclamation.svg);
				}
			
				@include most-outer-selector(".attr-error-403") {
					background-image: url(../../assets/images/svg/refusal.svg);
				}
			}
		}
	}

	&.style-a {}

	&.style-b {}

	&.type-c {
		.board-wrap {
			.board-head {
				align-items: center;
				text-align: center;
			}
			.board-body {
				align-items: center;
				text-align: center;
			}
		}
	}
}

/**
 * @type module
 * @name info-board
 * @modle c
**/
.info-board.module-c {
	.board-wrap {
		display: flex;
		flex-direction: column;
		row-gap: 48rem;

		.board-body {
			display: flex;
		}
	}

	&.type-c {
		.board-wrap {
			.board-body {
				justify-content: center;
			}
		}
	}

	&.style-a {
		.board-wrap {
			.board-body {
				padding : 32rem 0;
				background-color: color(primary, 005);
				border-radius: 8rem;

				>.para {
					@include font((outline: small-2x, size: 1.5)...);
					color: color(normal, 010);
				}
			}

			>.board-util {
				.button-display {
					display: flex;
		
					.button-area {
						flex: 1 1 100%;
						display: flex;
						column-gap: 8rem;
		
						.flex {
							flex: 1 1 100%;
						}
					}
				}
			}
		}
	}
}

/**
 * @tooltip
 * @ module-b
**/
.tooltip.module-b {
	display: flex;
	flex-direction: column;
	align-items: center;

	&::before {
		content: '';
		display: block;
		position: absolute;
		z-index: 1;
		top: 0;
		left: 50%;
		width: 12rem;
		height: 12rem;;
		background-color: color(normal, 000);
		transform: rotate(45deg) translate(calc(-50% - 2rem), 0);
		border-top: 1rem solid color(primary, 020);
		border-left: 1rem solid color(primary, 020);
		border-top-left-radius: 3rem;
	}

	.tooltip-wrap {
		display: flex;
		flex-direction: column;
		align-items: center;
		padding: 12rem;
		background-color: color(normal, 000);
		border: 1rem solid color(primary, 020);
		border-radius: 4rem;
		box-shadow: 0rem 0rem 12rem rgba(0, 0, 0, 0.08)	;

		.tooltip-head {
			.tooltip-summary {
				position: relative;
				margin: 0;
				@include font((outline: small-3x, size: 1.4)...);
				color: color(normal, 020);
				white-space: nowrap;
			}			
		}
	}

	&.type-b {}
	&.type-c {}
}

/**
 * @tooltip
 * @ module-c
**/
.tooltip.module-c {		
	position: absolute;
	z-index: 2;
	top: calc(100% + 4rem);
	right: 0;
	width: 120rem;
	padding: 8rem;
	background-color: color(normal, 000);
	box-shadow: 0rem 0rem 16rem rgba(0, 0, 0, 0.08);
	border-radius: 4rem;
	
	// &:not(.active) {
	// 	visibility: hidden;
	// 	opacity: 0;
	// }
					
	.tooltip-wrap {
		.tooltip-head {
			.tooltip-subject {
				margin: 0;

				.tooltip-name {
					@include hidden;
				}
			}
			
		}
		.tooltip-body {
			
			.navi-list {
				.navi-item {
					position: relative;
					padding: 6rem 8rem;
					background-color: color(base, 005);
					border-radius: 4rem;
					text-align: left;

					&:not(:hover){
						background-color: color(base, 000);
					}
					.navi-name {
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 010);
						text-decoration: none;
						cursor: pointer;

						&::before {
							content: '';
							display: block;
							position: absolute;
							top: 0;
							left: 0;
							right: 0;
							bottom: 0;
						}
					}
				}
			}
		}
	}
}

/**
 * @tooltip
 * @ module-d
**/
.tooltip.module-d {
	input[type="number"]::-webkit-outer-spin-button,
	input[type="number"]::-webkit-inner-spin-button {
		-webkit-appearance: none;
		margin: 0;
	}
	.tooltip-wrap {
		.tooltip-head {
			.tooltip-subject {
				margin: 0;

				.tooltip-name {
					@include hidden;
				}
			}
			
		}
		.tooltip-body {
			.form-area {
				display: flex;
				column-gap: 20rem;
				align-items: flex-end;

				.form {
					display: flex;
					flex-direction: column;
					align-items: center;
					row-gap: 4rem;

					.form-elem{
						flex: 1 1 auto;
						width: 56rem;
						height: 56rem;
						padding: 0;
						border: 1rem solid color(normal, 040);
						border-radius: 4rem;
						@include font((outline: small-2x, size: 1.5)...);
						color: color(normal, 010);
						text-align: center;

						&:focus-visible {
							outline-color: color(accent, 010 );
						}
					}

					.btn {
						width: 24rem;
						height: 24rem;
						background-color: color(accent, 010);
						mask-repeat: no-repeat;
						mask-position: center;
						mask-size: cover;

						&.step-up {
							mask-image: icon(chevron-up, color(normal, 030));
						}

						&.step-down {
							mask-image: icon(chevron-down, color(normal, 030));
						}

						.btn-text {
							@include hidden;
						}
					}

					.form-text {
						@include font((outline: small-3x, size: 1.4)...);
						color: color(normal, 030);
						text-align: center;
					}
				}
				.sign {
					color: color(normal, 010);
				}
			}
		}
	}

	&.style-b {
		background-color: color(normal, 000);
		box-shadow: 0rem 0rem 14rem rgba(0, 0, 0, 0.12);
		border-radius: 4rem;
		
		.tooltip-wrap {
			.tooltip-body {
				.submit-form {
					.form-list {
						padding: 20rem 40rem;
					}
				}
			}
		}

		.button-display {
			border-top: 1rem solid color(normal, 040);
		}
	}
}
